/// SwiftUI-shaped drawing context for `Canvas` renderers. Wraps the runtime
/// ``SwiftWindowsUI.CanvasGraphicsContext`` so operations flow through the
/// retained scene path (see ``ScenePainter``).
@MainActor
public struct GraphicsContext {
    /// Paint source for fill and stroke operations. Mirrors the SwiftUI
    /// `GraphicsContext.Shading` API surface for same-source compatibility.
    public enum Shading: Sendable {
        case color(Color)
        case linearGradient(gradient: Gradient, startPoint: CGPoint, endPoint: CGPoint)

        /// SwiftUI-compatible factory: matches the
        /// `GraphicsContext.Shading.linearGradient(_:startPoint:endPoint:)`
        /// shape used in shared demo code.
        public static func linearGradient(
            _ gradient: Gradient,
            startPoint: CGPoint,
            endPoint: CGPoint
        ) -> Shading {
            .linearGradient(gradient: gradient, startPoint: startPoint, endPoint: endPoint)
        }
    }

    /// Bridge into the runtime accumulator. Internal so ``Canvas`` can hand
    /// it back to the retained ``canvasDraw`` closure.
    internal var underlying: SwiftWindowsUI.CanvasGraphicsContext

    /// The resolver belongs to one Canvas render invocation. Copies of a
    /// context share its measured sources, but never retain another frame's
    /// environment or view state.
    internal var symbolResolver: ((AnyHashable) -> ResolvedSymbol?)?

    @MainActor
    public struct ResolvedSymbol {
        internal let source: SwiftWindowsUI.CanvasSymbolSource

        /// The view's measured size in logical points, before draw placement.
        public var size: CGSize { source.size }
    }

    /// Multiplied into the alpha of subsequent fill/stroke/draw operations,
    /// matching SwiftUI's ``GraphicsContext.opacity``.  Operations recorded
    /// before this property is set keep their original opacity.
    public var opacity: Double = 1.0

    /// Current transformation matrix applied to subsequent fill/stroke/draw
    /// operations, matching SwiftUI's ``GraphicsContext.transform``.  A non-
    /// identity transform converts rect-shaped fills into transformed path
    /// fills so rotation/shear remain visible.
    public var transform: CGAffineTransform = .identity

    public init() {
        self.underlying = SwiftWindowsUI.CanvasGraphicsContext()
    }

    // MARK: Transform stack

    // SwiftUI's translateBy/scaleBy/rotate match CGContext semantics: the new
    // matrix is pre-multiplied so subsequent drawing is transformed FIRST by
    // the new operation, then by any prior transform. That keeps the user
    // mental model intuitive — `translateBy(x: 60); rotate(90°); fill(rect)`
    // draws the rect rotated around the new (60, 0) origin.

    public mutating func translateBy(x: Double, y: Double) {
        transform = CGAffineTransform(translationX: x, y: y).concatenating(transform)
    }

    public mutating func scaleBy(x: Double, y: Double) {
        transform = CGAffineTransform(scaleX: x, y: y).concatenating(transform)
    }

    public mutating func rotate(by angle: Angle) {
        transform = CGAffineTransform(rotationAngle: angle.radians).concatenating(transform)
    }

    public mutating func concatenate(_ matrix: CGAffineTransform) {
        transform = matrix.concatenating(transform)
    }

    // MARK: Path / rect fill

    public mutating func fill(_ path: Path, with shading: Shading, style: FillStyle = FillStyle()) {
        let transformed = transformedPath(path)
        underlying.fill(
            transformed,
            with: shading.asRuntimeShading(
                opacity: currentOpacityMultiplier,
                transform: transform,
                preservesGradientGeometry: true
            ),
            style: style
        )
    }

    public mutating func fill(_ rect: CGRect, with shading: Shading) {
        if isTransformIdentity {
            underlying.fill(rect, with: shading.asRuntimeShading(opacity: currentOpacityMultiplier))
        } else {
            underlying.fill(
                rectAsTransformedPath(rect),
                with: shading.asRuntimeShading(
                    opacity: currentOpacityMultiplier,
                    transform: transform,
                    preservesGradientGeometry: true
                )
            )
        }
    }

    // MARK: Path / rect stroke

    public mutating func stroke(_ path: Path, with shading: Shading, lineWidth: Double = 1) {
        underlying.stroke(
            transformedPath(path),
            with: shading.asRuntimeShading(
                opacity: currentOpacityMultiplier,
                transform: transform,
                preservesGradientGeometry: true
            ),
            style: StrokeStyle(lineWidth: lineWidth)
        )
    }

    public mutating func stroke(_ path: Path, with shading: Shading, style: StrokeStyle) {
        underlying.stroke(
            transformedPath(path),
            with: shading.asRuntimeShading(
                opacity: currentOpacityMultiplier,
                transform: transform,
                preservesGradientGeometry: true
            ),
            style: style
        )
    }

    public mutating func stroke(_ rect: CGRect, with shading: Shading, lineWidth: Double = 1) {
        if isTransformIdentity {
            underlying.stroke(
                rect,
                with: shading.asRuntimeShading(
                    opacity: currentOpacityMultiplier,
                    transform: transform,
                    preservesGradientGeometry: true
                ),
                lineWidth: lineWidth
            )
        } else {
            underlying.stroke(
                rectAsTransformedPath(rect),
                with: shading.asRuntimeShading(
                    opacity: currentOpacityMultiplier,
                    transform: transform,
                    preservesGradientGeometry: true
                ),
                style: StrokeStyle(lineWidth: lineWidth)
            )
        }
    }

    // MARK: Image / text

    public func resolveSymbol<ID: Hashable>(id: ID) -> ResolvedSymbol? {
        symbolResolver?(AnyHashable(id))
    }

    public mutating func draw(
        _ symbol: ResolvedSymbol,
        at point: CGPoint,
        anchor: UnitPoint = .center
    ) {
        draw(
            symbol,
            in: CGRect(
                x: point.x - symbol.size.width * anchor.x,
                y: point.y - symbol.size.height * anchor.y,
                width: symbol.size.width,
                height: symbol.size.height))
    }

    public mutating func draw(_ symbol: ResolvedSymbol, in rect: CGRect) {
        underlying.draw(
            symbol.source, in: rect, transform: transform,
            opacity: Float(currentOpacityMultiplier))
    }

    public mutating func draw(_ image: BitmapSurface, in rect: CGRect, opacity: Float = 1) {
        // Images can only be drawn into axis-aligned rects today; degenerate
        // transforms collapse to the transformed bounding rect.
        let drawRect = transformedAxisAlignedRect(rect)
        underlying.draw(image, in: drawRect, opacity: opacity * Float(currentOpacityMultiplier))
    }

    public mutating func draw(_ text: Text, at point: CGPoint) {
        let resolved = text.plainContent
        guard !resolved.isEmpty else { return }
        underlying.draw(resolved, at: point, style: textPixelStyle())
    }

    public mutating func draw(_ text: Text, in rect: CGRect) {
        let resolved = text.plainContent
        guard !resolved.isEmpty else { return }
        underlying.draw(resolved, in: rect, style: textPixelStyle())
    }

    public mutating func draw(_ string: String, at point: CGPoint, style: PixelTextStyle) {
        underlying.draw(string, at: point, style: style.multipliedOpacity(by: Float(currentOpacityMultiplier)))
    }

    public mutating func draw(_ string: String, in rect: CGRect, style: PixelTextStyle) {
        underlying.draw(string, in: rect, style: style.multipliedOpacity(by: Float(currentOpacityMultiplier)))
    }

    // MARK: Clip stack

    public mutating func clip(to rect: CGRect) {
        underlying.clip(to: rect)
    }

    public mutating func popClip() {
        underlying.popClip()
    }

    // MARK: Layer scope

    /// Run `content` with a sub-context that inherits this context's
    /// transform, opacity and clip state while drawing to the same destination.
    /// Transient state mutations inside the closure don't leak back out, and
    /// operations keep their invocation order. This scopes graphics state;
    /// separate layer blending and filtering are not implemented here.
    public mutating func drawLayer(content: (inout GraphicsContext) -> Void) {
        var sub = self
        content(&sub)
    }

    // MARK: Helpers

    private var currentOpacityMultiplier: Double {
        max(0, min(1, opacity))
    }

    private var isTransformIdentity: Bool {
        transform == .identity
    }

    private func textPixelStyle() -> PixelTextStyle {
        PixelTextStyle(color: .white).multipliedOpacity(by: Float(currentOpacityMultiplier))
    }

    private func transformedPath(_ path: Path) -> Path {
        guard !isTransformIdentity else { return path }
        // SwiftWindowsCore's `Path.applying(_:)` already walks every element
        // and runs control + endpoint coords through the affine transform.
        // Arc radii are kept as-is — non-uniform scale/rotation of arcs is a
        // future improvement that would require sampling them into cubics
        // first.
        return path.applying(transform)
    }

    private func rectAsTransformedPath(_ rect: CGRect) -> Path {
        var path = Path()
        let p0 = transform.apply(Point(x: rect.minX, y: rect.minY))
        let p1 = transform.apply(Point(x: rect.maxX, y: rect.minY))
        let p2 = transform.apply(Point(x: rect.maxX, y: rect.maxY))
        let p3 = transform.apply(Point(x: rect.minX, y: rect.maxY))
        path.moveTo(p0)
        path.lineTo(p1)
        path.lineTo(p2)
        path.lineTo(p3)
        path.close()
        return path
    }

    private func transformedAxisAlignedRect(_ rect: CGRect) -> CGRect {
        guard !isTransformIdentity else { return rect }
        let p0 = transform.apply(Point(x: rect.minX, y: rect.minY))
        let p1 = transform.apply(Point(x: rect.maxX, y: rect.minY))
        let p2 = transform.apply(Point(x: rect.maxX, y: rect.maxY))
        let p3 = transform.apply(Point(x: rect.minX, y: rect.maxY))
        let minX = min(p0.x, p1.x, p2.x, p3.x)
        let maxX = max(p0.x, p1.x, p2.x, p3.x)
        let minY = min(p0.y, p1.y, p2.y, p3.y)
        let maxY = max(p0.y, p1.y, p2.y, p3.y)
        return CGRect(x: minX, y: minY, width: maxX - minX, height: maxY - minY)
    }
}

extension GraphicsContext.Shading {
    /// Convert a SwiftUI-shaped Shading into the runtime's
    /// ``CanvasGraphicsContext.Shading`` enum that the scene/frame paths can
    /// consume.  `opacity` is folded into the shading's alpha so the runtime
    /// does not need to know about the wrapping GraphicsContext.opacity.
    internal func asRuntimeShading(
        opacity: Double = 1.0,
        transform: CGAffineTransform = .identity,
        preservesGradientGeometry: Bool = false
    ) -> SwiftWindowsUI.CanvasGraphicsContext.Shading {
        let alpha = Float(max(0, min(1, opacity)))
        switch self {
        case .color(let color):
            return .color(color.multipliedAlpha(by: alpha))
        case .linearGradient(let gradient, let startPoint, let endPoint):
            // The path is transformed before it reaches the runtime, so its
            // gradient endpoints must move through that same matrix. Path
            // gradients retain the complete vector, including diagonals;
            // unpositioned gradient quads keep their dominant-axis fast path.
            let transformedStartPoint = transform.apply(startPoint)
            let transformedEndPoint = transform.apply(endPoint)
            let axis: SwiftWindowsGraphics.GradientAxis = {
                let dx = abs(transformedEndPoint.x - transformedStartPoint.x)
                let dy = abs(transformedEndPoint.y - transformedStartPoint.y)
                return dx >= dy ? .horizontal : .vertical
            }()
            let isReversed =
                axis == .horizontal
                ? transformedEndPoint.x < transformedStartPoint.x
                : transformedEndPoint.y < transformedStartPoint.y
            let authoredStops = isReversed ? Array(gradient.stops.reversed()) : gradient.stops
            let stops = authoredStops.map { stop in
                SwiftWindowsGraphics.GradientStop(
                    color: stop.color.multipliedAlpha(by: alpha),
                    position: isReversed ? 1 - stop.position : stop.position
                )
            }
            let runtimeGradient: SwiftWindowsGraphics.LinearGradient
            if stops.isEmpty {
                runtimeGradient = SwiftWindowsGraphics.LinearGradient(
                    startColor: .clear, endColor: .clear, axis: axis)
            } else {
                runtimeGradient = SwiftWindowsGraphics.LinearGradient(
                    stops: stops, axis: axis, reversesAuthoredStops: isReversed)
            }

            guard preservesGradientGeometry,
                transformedStartPoint.x.isFinite,
                transformedStartPoint.y.isFinite,
                transformedEndPoint.x.isFinite,
                transformedEndPoint.y.isFinite
            else {
                // Rect fills deliberately keep the existing gradient-quad
                // fast path, and invalid geometry never reaches path hashes.
                return .gradient(runtimeGradient)
            }

            // Reversed authored stops already run from the lower coordinate
            // toward the higher one; swapping the endpoints here avoids
            // reversing the ramp a second time in the path rasterizer.
            return .positionedGradient(
                runtimeGradient,
                startPoint: isReversed ? transformedEndPoint : transformedStartPoint,
                endPoint: isReversed ? transformedStartPoint : transformedEndPoint
            )
        }
    }
}

