@MainActor
public final class UndoManager: @unchecked Sendable {
    private final class UndoAction {
        weak var target: AnyObject?
        let targetIdentifier: ObjectIdentifier
        var name: String
        let handler: @MainActor (AnyObject) -> Void

        init(target: AnyObject, name: String, handler: @escaping @MainActor (AnyObject) -> Void) {
            self.target = target
            targetIdentifier = ObjectIdentifier(target)
            self.name = name
            self.handler = handler
        }
    }

    private var undoStack: [UndoAction] = []
    private var redoStack: [UndoAction] = []
    private var pendingActionName = ""
    private var registrationDisableCount = 0
    private weak var replayAction: UndoAction?
    private var isProcessingReplay = false

    public private(set) var isUndoing = false
    public private(set) var isRedoing = false

    public init() {}

    public var canUndo: Bool {
        pruneDeadTargets()
        return !undoStack.isEmpty
    }

    public var canRedo: Bool {
        pruneDeadTargets()
        return !redoStack.isEmpty
    }

    public var undoActionName: String {
        pruneDeadTargets()
        return undoStack.last?.name ?? ""
    }

    public var redoActionName: String {
        pruneDeadTargets()
        return redoStack.last?.name ?? ""
    }

    public var isUndoRegistrationEnabled: Bool {
        registrationDisableCount == 0
    }

    public func disableUndoRegistration() {
        registrationDisableCount += 1
    }

    public func enableUndoRegistration() {
        // Foundation raises NSInternalInconsistencyException for an
        // unmatched enable. The Windows compatibility layer uses a
        // precondition because Objective-C exceptions are unavailable.
        precondition(
            registrationDisableCount > 0,
            "enableUndoRegistration() requires a matching disableUndoRegistration()."
        )
        registrationDisableCount -= 1
    }

    public func registerUndo<TargetType: AnyObject>(
        withTarget target: TargetType,
        handler: @escaping @MainActor (TargetType) -> Void
    ) {
        _ = recordUndo(withTarget: target, actionName: nil, handler: handler)
    }

    @discardableResult
    func registerUndo<TargetType: AnyObject>(
        withTarget target: TargetType, actionName: String,
        handler: @escaping @MainActor (TargetType) -> Void
    ) -> Bool {
        recordUndo(withTarget: target, actionName: actionName, handler: handler)
    }

    private func recordUndo<TargetType: AnyObject>(
        withTarget target: TargetType, actionName: String?,
        handler: @escaping @MainActor (TargetType) -> Void
    ) -> Bool {
        guard isUndoRegistrationEnabled else { return false }
        pruneDeadTargets()
        guard isUndoRegistrationEnabled else { return false }
        let action = UndoAction(target: target, name: actionName ?? pendingActionName) { target in
            guard let target = target as? TargetType else { return }
            handler(target)
        }
        pendingActionName = ""

        if isUndoing {
            redoStack.append(action)
        } else {
            undoStack.append(action)
            if !isRedoing {
                let previousRedoStack = redoStack
                withExtendedLifetime(previousRedoStack) {
                    redoStack = []
                }
            }
        }
        if isUndoing || isRedoing {
            replayAction = action
        }
        return true
    }

    public func setActionName(_ actionName: String) {
        pruneDeadTargets()
        if isUndoing || isRedoing {
            if let replayAction {
                replayAction.name = actionName
            } else {
                pendingActionName = actionName
            }
        } else if let action = undoStack.last {
            action.name = actionName
        } else {
            pendingActionName = actionName
        }
    }

    public func undo() {
        processReplay(undoing: true)
    }

    public func redo() {
        processReplay(undoing: false)
    }

    func undo(allowingTarget predicate: @escaping @MainActor (AnyObject) -> Bool) {
        processReplay(undoing: true, allowingTarget: predicate)
    }

    func redo(allowingTarget predicate: @escaping @MainActor (AnyObject) -> Bool) {
        processReplay(undoing: false, allowingTarget: predicate)
    }

    private func processReplay(undoing: Bool, allowingTarget predicate: (@MainActor (AnyObject) -> Bool)? = nil) {
        guard !isProcessingReplay else { return }
        isProcessingReplay = true
        defer { isProcessingReplay = false }
        performReplay(undoing: undoing, allowingTarget: predicate)
    }

    private func performReplay(undoing: Bool, allowingTarget predicate: (@MainActor (AnyObject) -> Bool)?) {
        // Keep the request guard active while pruning or releasing an
        // executed action. Captured payloads can deinitialize and attempt
        // another replay even outside the handler's public replay phase.
        pruneDeadTargets()
        let action = undoing ? undoStack.last : redoStack.last
        guard let action, let target = action.target else { return }
        guard predicate?(target) ?? true,
            action === (undoing ? undoStack.last : redoStack.last), action.target === target
        else { return }
        if let editor = target as? any UndoManagerReplayTarget, !editor.prepareForUndoReplay() { return }
        guard predicate?(target) ?? true else { return }
        // Preflight can rebuild content, remove a target, or release captured
        // payloads. Never consume a replacement action installed by that work.
        guard action === (undoing ? undoStack.last : redoStack.last), action.target === target else { return }
        if undoing { undoStack.removeLast() } else { redoStack.removeLast() }
        isUndoing = undoing
        isRedoing = !undoing
        pendingActionName = ""
        defer {
            isUndoing = false
            isRedoing = false
            replayAction = nil
            pendingActionName = ""
        }
        action.handler(target)
    }

    public func removeAllActions() {
        pendingActionName = ""
        registrationDisableCount = 0
        removeActions { _ in true }
    }

    public func removeAllActions(withTarget target: Any) {
        let identifier = ObjectIdentifier(target as AnyObject)
        removeActions { action in
            action.targetIdentifier == identifier || action.target == nil
        }
    }

    private func pruneDeadTargets() {
        guard undoStack.contains(where: { $0.target == nil }) || redoStack.contains(where: { $0.target == nil }) else {
            return
        }
        removeActions { $0.target == nil }
    }

    private func removeActions(where shouldRemove: (UndoAction) -> Bool) {
        let previousUndoStack = undoStack
        let previousRedoStack = redoStack
        // Release captured action payloads only after both stored stacks
        // have been replaced. Their deinitializers can call back into this
        // manager without overlapping an array mutation or seeing half a clear.
        withExtendedLifetime((previousUndoStack, previousRedoStack)) {
            undoStack = previousUndoStack.filter { !shouldRemove($0) }
            redoStack = previousRedoStack.filter { !shouldRemove($0) }
        }
    }
}
public struct OpenURLAction: @unchecked Sendable {
    public enum Result: Sendable, Equatable {
        case handled
        case discarded
        case systemAction
    }

    private let handler: @MainActor (URL) -> Result
    // Only the framework default may be routed through a native owner. A
    // caller's custom synchronous action keeps its actual Result semantics.
    let isSystemAction: Bool

    public init(handler: @escaping @MainActor (URL) -> Result) {
        self.handler = handler
        isSystemAction = false
    }

    private init(systemHandler: @escaping @MainActor (URL) -> Result) {
        handler = systemHandler
        isSystemAction = true
    }

    @discardableResult
    @MainActor
    public func callAsFunction(_ url: URL) -> Result {
        handler(url)
    }

    public static let system = OpenURLAction(systemHandler: { url in
        defaultOpenURL(url) ? .handled : .discarded
    })
}
