    /// A state write is a new mutation, whereas a control's explicit
    /// invalidation can follow a binding write whose scope has already ended.
    /// Hosts use this distinction to preserve the right transaction without
    /// storing invalidation provenance in process-global UI state.
    func invalidateStateMutation() {
        stateMutationInvalidationHandler()
    }

    func observe(_ object: any ObservableObject) {
        if let attribution = viewIdentity.lazyList {
            guard let stateMountCoordinator, let owner = viewIdentity.installedOwner,
                attribution.admission.isCurrent,
                let group = attribution.native.registerGroup(kind: .objectDependency), attribution.admission.isCurrent
            else { return }
            stateMountCoordinator.stageLazyDependency(object, owner: owner, attribution: attribution, group: group)
            return
        }
        if let attribution = viewIdentity.descriptorComponent {
            guard let stateMountCoordinator, let owner = viewIdentity.installedOwner, attribution.canConstruct,
                let group = attribution.registerGroup(kind: .objectDependency), attribution.canConstruct
            else { return }
            stateMountCoordinator.stageDescriptorDependency(
                object, owner: owner, attribution: attribution, group: group)
            return
        }
        if let stateMountCoordinator {
            stateMountCoordinator.observe(object, at: viewIdentity.installedOwner?.identity ?? retainedViewIdentity)
        } else {
            observedObjectHandler(object)
        }
    }

    func pushNavigationDestination(
        _ destination: [AnyView],
        onDismiss: NavigationDestinationDismissHandler? = nil
    ) -> Bool {
        guard let handler = navigationDestinationHandlerProvider() else {
            return false
        }

        handler(destination, onDismiss)
        return true
    }

    func pushNavigationValue(_ value: AnyHashable) -> Bool {
        guard let handler = navigationValueHandlerProvider() else {
            return false
        }

        return handler(value)
    }

    /// Derives a context whose canvas is the slot a container is about to
    /// hand its content, rather than the whole window.
    ///
    /// `GeometryReader` reads its proxy from the canvas at build time, so a
    /// container that consumes chrome above or beside its content (a tab
    /// bar, a toolbar band) must subtract that chrome here or every reader
    /// underneath over-reports by exactly the chrome extent and the page
    /// runs off the window edge.
    func withCanvasSize(_ size: Size) -> ViewBuildContext {
        let clamped = Size(width: max(0, size.width), height: max(0, size.height))
        return ViewBuildContext(
            viewIdentity: viewIdentity,
            stateMountCoordinator: stateMountCoordinator,
            nativeDialogSession: nativeDialogSession,
            nativeDialogOwnerRequest: nativeDialogOwnerRequest,
            canvasSizeProvider: { clamped },
            invalidateHandler: invalidateHandler,
            stateMutationInvalidationHandler: stateMutationInvalidationHandler,
            observedObjectHandler: observedObjectHandler,
            isEnabledProvider: isEnabledProvider,
            foregroundColorProvider: foregroundColorProvider,
            tintProvider: tintProvider,
            fontProvider: fontProvider,
            fontDesignProvider: fontDesignProvider,
            fontWeightProvider: fontWeightProvider,
            textAlignmentProvider: textAlignmentProvider,
            lineLimitProvider: lineLimitProvider,
            truncationModeProvider: truncationModeProvider,
            allowsTighteningProvider: allowsTighteningProvider,
            textCaseProvider: textCaseProvider,
            labelsHiddenProvider: labelsHiddenProvider,
            controlSizeProvider: controlSizeProvider,
            stackAxisProvider: stackAxisProvider,
            buttonStyleProvider: buttonStyleProvider,
            pickerStyleProvider: pickerStyleProvider,
            environmentValuesProvider: environmentValuesProvider,
            navigationDestinationHandlerProvider: navigationDestinationHandlerProvider,
            navigationValueHandlerProvider: navigationValueHandlerProvider,
            navigationDestinationRegistrationsProvider: navigationDestinationRegistrationsProvider,
            navigationPresentedDestinationsProvider: navigationPresentedDestinationsProvider
        )
    }

