            String(reflecting: id),
            { dimensions in
                id.defaultValue(in: dimensions)
            })
    }

    var retainedGuideName: String {
        switch self {
        case .leading:
            return "leading"
        case .center:
            return "center"
        case .trailing:
            return "trailing"
        case .custom(let name, _):
            return "custom:\(name)"
        }
    }
}
