public struct ViewDimensions: Sendable, Equatable {
    public var width: CGFloat
    public var height: CGFloat

    public init(width: CGFloat = 0, height: CGFloat = 0) {
        self.width = width
        self.height = height
    }

    public init(size: CGSize) {
        self.init(width: size.width, height: size.height)
    }

    public subscript(guide: HorizontalAlignment) -> CGFloat {
        switch guide {
        case .leading:
            return 0
        case .center:
            return width / 2
        case .trailing:
            return width
        case .custom(_, let defaultValue):
            return defaultValue(self)
        }
    }

    public subscript(guide: VerticalAlignment) -> CGFloat {
        switch guide {
        case .top:
            return 0
        case .center:
            return height / 2
        case .bottom:
            return height
        case .firstTextBaseline, .lastTextBaseline:
            return height * 0.8
        case .custom(_, let defaultValue):
            return defaultValue(self)
        }
    }

    public subscript(explicit guide: HorizontalAlignment) -> CGFloat? {
        self[guide]
    }

    public subscript(explicit guide: VerticalAlignment) -> CGFloat? {
        self[guide]
    }
}
