    public static let error = SensoryFeedback(kind: .error)
    public static let impact = SensoryFeedback(kind: .impact)
    public static let increase = SensoryFeedback(kind: .increase)
    public static let levelChange = SensoryFeedback(kind: .levelChange)
    public static let pathComplete = SensoryFeedback(kind: .pathComplete)
    public static let selection = SensoryFeedback(kind: .selection)
    public static let start = SensoryFeedback(kind: .start)
    public static let stop = SensoryFeedback(kind: .stop)
    public static let success = SensoryFeedback(kind: .success)
    public static let warning = SensoryFeedback(kind: .warning)

    public static func impact(weight: Weight = .medium, intensity: Double = 1.0) -> SensoryFeedback {
        SensoryFeedback(kind: .impactWeight(weight, intensity))
    }

    public static func impact(flexibility: Flexibility, intensity: Double = 1.0) -> SensoryFeedback {
        SensoryFeedback(kind: .impactFlexibility(flexibility, intensity))
    }

    public static func press(_ feedback: PressFeedback = .default) -> SensoryFeedback {
        SensoryFeedback(kind: .press(feedback))
    }

    public static func release(_ feedback: ReleaseFeedback = .default) -> SensoryFeedback {
        SensoryFeedback(kind: .release(feedback))
    }

    public static func selection(_ feedback: SelectionFeedback = .default) -> SensoryFeedback {
        SensoryFeedback(kind: .selectionFeedback(feedback))
    }

    var retained: RetainedSensoryFeedback {
        switch kind {
        case .alignment:
            return RetainedSensoryFeedback(kind: .alignment)
        case .decrease:
            return RetainedSensoryFeedback(kind: .decrease)
        case .error:
            return RetainedSensoryFeedback(kind: .error)
        case .impact:
            return RetainedSensoryFeedback(kind: .impact)
        case .impactFlexibility(let flexibility, let intensity):
            let flexibilityKind: RetainedSensoryFeedback.FlexibilityKind =
                switch flexibility.kind {
                case .rigid: .rigid
                case .solid: .solid
                case .soft: .soft
                }
            return RetainedSensoryFeedback(kind: .impactFlexibility, flexibility: flexibilityKind, intensity: intensity)
        case .impactWeight(let weight, let intensity):
            let weightKind: RetainedSensoryFeedback.WeightKind =
                switch weight.kind {
                case .light: .light
                case .medium: .medium
                case .heavy: .heavy
                }
            return RetainedSensoryFeedback(kind: .impactWeight, weight: weightKind, intensity: intensity)
        case .increase:
            return RetainedSensoryFeedback(kind: .increase)
        case .levelChange:
            return RetainedSensoryFeedback(kind: .levelChange)
        case .pathComplete:
            return RetainedSensoryFeedback(kind: .pathComplete)
        case .press(let feedback):
            let pressKind: RetainedSensoryFeedback.PressKind =
                switch feedback.kind {
                case .default: .default
                case .depth: .depth
                case .start: .start
                }
            return RetainedSensoryFeedback(kind: .press, pressKind: pressKind)
        case .release(let feedback):
            let releaseKind: RetainedSensoryFeedback.ReleaseKind =
                switch feedback.kind {
                case .default: .default
                case .stop: .stop
                }
            return RetainedSensoryFeedback(kind: .release, releaseKind: releaseKind)
        case .selection:
            return RetainedSensoryFeedback(kind: .selection)
        case .selectionFeedback(let feedback):
            let selectionKind: RetainedSensoryFeedback.SelectionKind =
                switch feedback.kind {
                case .default: .default
                case .maximum: .maximum
                case .minimum: .minimum
                case .off: .off
                case .on: .on
                }
            return RetainedSensoryFeedback(kind: .selectionFeedback, selectionKind: selectionKind)
        case .start:
            return RetainedSensoryFeedback(kind: .start)
        case .stop:
            return RetainedSensoryFeedback(kind: .stop)
        case .success:
            return RetainedSensoryFeedback(kind: .success)
        case .warning:
            return RetainedSensoryFeedback(kind: .warning)
        }
    }
