public enum SubmitLabel: Sendable, Equatable {
    case `return`
    case done
    case go
    case send
    case join
    case route
    case search
    case next
    case `continue`

    var retainedSubmitLabel: RetainedSubmitLabel {
        switch self {
        case .return:
            return .return
        case .done:
            return .done
        case .go:
            return .go
        case .send:
            return .send
        case .join:
            return .join
        case .route:
            return .route
        case .search:
            return .search
        case .next:
            return .next
        case .continue:
            return .continue
        }
    }
}
public struct Font: Sendable, Equatable {
    public enum Weight: Sendable, Equatable {
        case ultraLight
        case thin
        case light
        case regular
        case medium
        case semibold
        case bold
        case heavy
        case black
    }

    public enum Design: Sendable, Equatable {
        case `default`
        case serif
        case rounded
        case monospaced
    }

    public enum Width: Sendable, Equatable {
        case compressed
        case condensed
        case standard
        case expanded
    }

    public enum TextStyle: Sendable, Equatable {
        case largeTitle
        case title
        case title2
        case title3
        case headline
        case subheadline
        case body
        case callout
        case footnote
        case caption
        case caption2
    }

    public enum Leading: Sendable, Equatable {
        case standard
        case tight
        case loose
    }

    public var size: Double
    public var weight: Weight
    public var design: Design
    public var width: Width
    public var family: String?
    public var leading: Leading
    public var scalesWithDynamicType: Bool
    public var isItalic: Bool
    public var usesMonospacedDigits: Bool
    public var usesLowercaseSmallCaps: Bool
    public var usesUppercaseSmallCaps: Bool

    public init(
        size: Double,
        weight: Weight = .regular,
        design: Design = .default,
        width: Width = .standard,
        family: String? = nil,
        leading: Leading = .standard,
        scalesWithDynamicType: Bool = true,
        isItalic: Bool = false,
        usesMonospacedDigits: Bool = false,
        usesLowercaseSmallCaps: Bool = false,
        usesUppercaseSmallCaps: Bool = false
    ) {
        self.size = size
        self.weight = weight
        self.design = design
        self.width = width
        self.family = family
        self.leading = leading
        self.scalesWithDynamicType = scalesWithDynamicType
        self.isItalic = isItalic
        self.usesMonospacedDigits = usesMonospacedDigits
        self.usesLowercaseSmallCaps = usesLowercaseSmallCaps
        self.usesUppercaseSmallCaps = usesUppercaseSmallCaps
    }

    public static func system(size: Double, weight: Weight = .regular, design: Design = .default) -> Font {
        Font(size: size, weight: weight, design: design)
    }

    public static func system(_ style: TextStyle, design: Design? = nil, weight: Weight? = nil) -> Font {
        let font = defaultFont(for: style)
        return Font(
            size: font.size,
            weight: weight ?? font.weight,
            design: design ?? font.design,
            width: font.width,
            family: font.family,
            leading: font.leading,
            scalesWithDynamicType: font.scalesWithDynamicType,
            isItalic: font.isItalic,
            usesMonospacedDigits: font.usesMonospacedDigits,
            usesLowercaseSmallCaps: font.usesLowercaseSmallCaps,
            usesUppercaseSmallCaps: font.usesUppercaseSmallCaps
        )
    }

    public static func custom(_ name: String, size: CGFloat) -> Font {
        Font(size: size, family: name)
    }

    public static func custom(_ name: String, fixedSize: CGFloat) -> Font {
        Font(size: fixedSize, family: name, scalesWithDynamicType: false)
    }

    public static func custom(_ name: String, size: CGFloat, relativeTo textStyle: TextStyle) -> Font {
        let font = defaultFont(for: textStyle)
        return Font(
            size: size,
            weight: font.weight,
            design: font.design,
            width: font.width,
            family: name,
            leading: font.leading,
            scalesWithDynamicType: font.scalesWithDynamicType,
            isItalic: font.isItalic,
            usesMonospacedDigits: font.usesMonospacedDigits,
            usesLowercaseSmallCaps: font.usesLowercaseSmallCaps,
            usesUppercaseSmallCaps: font.usesUppercaseSmallCaps
        )
    }

    // The macOS system ramp, read from `MacOSControlMetrics.Typography` so
    // the type and the control boxes it has to fit in are pinned by one
    // module. These used to be the iOS Dynamic Type table at `.large`
    // (body 17, largeTitle 34) under the name "macOS parity", which is why
    // a 17pt label was being asked to sit in a 21pt text field.
    public static let largeTitle = Font(size: MacOSControlMetrics.Typography.largeTitleSize)
    public static let title = Font(size: MacOSControlMetrics.Typography.titleSize)
    public static let title2 = Font(size: MacOSControlMetrics.Typography.title2Size)
    public static let title3 = Font(size: MacOSControlMetrics.Typography.title3Size)
    public static let headline = Font(size: MacOSControlMetrics.Typography.headlineSize, weight: .semibold)
    public static let subheadline = Font(size: MacOSControlMetrics.Typography.subheadlineSize)
    public static let body = Font(size: MacOSControlMetrics.Typography.bodySize)
    public static let callout = Font(size: MacOSControlMetrics.Typography.calloutSize)
    public static let footnote = Font(size: MacOSControlMetrics.Typography.footnoteSize)
    public static let caption = Font(size: MacOSControlMetrics.Typography.captionSize)
    public static let caption2 = Font(size: MacOSControlMetrics.Typography.caption2Size)

    public func weight(_ weight: Weight) -> Font {
        Font(
            size: size,
            weight: weight,
            design: design,
            width: width,
            family: family,
            leading: leading,
            scalesWithDynamicType: scalesWithDynamicType,
            isItalic: isItalic,
            usesMonospacedDigits: usesMonospacedDigits,
            usesLowercaseSmallCaps: usesLowercaseSmallCaps,
            usesUppercaseSmallCaps: usesUppercaseSmallCaps
        )
    }

    public func bold() -> Font {
        bold(true)
    }

    public func bold(_ isActive: Bool) -> Font {
        weight(isActive ? .bold : .regular)
    }

    public func italic() -> Font {
        italic(true)
    }

    public func italic(_ isActive: Bool) -> Font {
        var copy = self
        copy.isItalic = isActive
        return copy
    }

    public func monospaced() -> Font {
        monospaced(true)
    }

    public func monospaced(_ isActive: Bool) -> Font {
        withDesign(isActive ? .monospaced : .default)
    }

    public func monospacedDigit() -> Font {
        var copy = self
        copy.usesMonospacedDigits = true
        return copy
    }

    public func smallCaps() -> Font {
        smallCaps(true)
    }

    public func smallCaps(_ isActive: Bool) -> Font {
        var copy = self
        copy.usesLowercaseSmallCaps = isActive
        copy.usesUppercaseSmallCaps = isActive
        return copy
    }

    public func lowercaseSmallCaps() -> Font {
        lowercaseSmallCaps(true)
    }

    public func lowercaseSmallCaps(_ isActive: Bool) -> Font {
        var copy = self
        copy.usesLowercaseSmallCaps = isActive
        return copy
    }

    public func uppercaseSmallCaps() -> Font {
        uppercaseSmallCaps(true)
    }

    public func uppercaseSmallCaps(_ isActive: Bool) -> Font {
        var copy = self
        copy.usesUppercaseSmallCaps = isActive
        return copy
    }

    public func leading(_ leading: Leading) -> Font {
        Font(
            size: size,
            weight: weight,
            design: design,
            width: width,
            family: family,
            leading: leading,
            scalesWithDynamicType: scalesWithDynamicType,
            isItalic: isItalic,
            usesMonospacedDigits: usesMonospacedDigits,
            usesLowercaseSmallCaps: usesLowercaseSmallCaps,
            usesUppercaseSmallCaps: usesUppercaseSmallCaps
        )
    }

    public func width(_ width: Width) -> Font {
        Font(
            size: size,
            weight: weight,
            design: design,
            width: width,
            family: family,
            leading: leading,
            scalesWithDynamicType: scalesWithDynamicType,
            isItalic: isItalic,
            usesMonospacedDigits: usesMonospacedDigits,
            usesLowercaseSmallCaps: usesLowercaseSmallCaps,
            usesUppercaseSmallCaps: usesUppercaseSmallCaps
        )
    }

    private static func defaultFont(for style: TextStyle) -> Font {
        switch style {
        case .largeTitle:
            return .largeTitle
        case .title:
            return .title
        case .title2:
            return .title2
        case .title3:
            return .title3
        case .headline:
            return .headline
        case .subheadline:
            return .subheadline
        case .body:
            return .body
        case .callout:
            return .callout
        case .footnote:
            return .footnote
        case .caption:
            return .caption
        case .caption2:
            return .caption2
        }
    }

    public struct Resolved: Sendable, Equatable {
        public let font: Font
        public init(font: Font) { self.font = font }
    }

    public func resolve(in environment: EnvironmentValues) -> Resolved {
        Resolved(font: self)
    }
}
public struct ButtonSurfaceStyle: Sendable {
    public var cornerRadius: Double
    public var palette: SurfacePalette
    public var chrome: SurfaceChrome
    public var clipsToBounds: Bool
    public var animation: ControlAnimationStyle

    /// macOS push buttons are a rounded rectangle at
    /// `MacOSControlMetrics.Button.regularCornerRadius`. The default used
    /// to be 16, which a 22–30pt control clamps to h/2 — every button in
    /// the app rendered as a capsule.
    public init(
        cornerRadius: Double = MacOSControlMetrics.Button.regularCornerRadius,
        palette: SurfacePalette = ButtonSurfaceStyle.defaultPalette,
        chrome: SurfaceChrome = .elevatedButton,
        clipsToBounds: Bool = true,
        animation: ControlAnimationStyle = .default
    ) {
        self.cornerRadius = cornerRadius
        self.palette = palette
        self.chrome = chrome
        self.clipsToBounds = clipsToBounds
        self.animation = animation
    }

    /// Dark-appearance bordered chrome. Builders that can see a
    /// `ViewBuildContext` should call `bordered(palette:)` instead so the
    /// surface follows `colorScheme`; this stays as the appearance-free
    /// fallback for the handful of call sites that have no context.
    public static let `default` = ButtonSurfaceStyle.bordered(palette: .darkStandard)
    /// `.plain` / `.borderless` / `.link`: an AppKit button with
    /// `isBordered == false`. There is no bezel in any state, so there is no
    /// fill to move on press — AppKit answers one by darkening the button's
    /// *contents* (`NSCell.StyleMask.contentsCellMask`), which is what
    /// `pressedContentOpacity` is.
    ///
    /// It has to be stated here because it is the one ramp the geometric
    /// press scale was carrying on its own: a transparent surface plus a
    /// removed shrink is a control that does not acknowledge the pointer.
    public static let plain = ButtonSurfaceStyle(
        cornerRadius: 0,
        palette: SurfacePalette(
            idle: .clear,
            hovered: .clear,
            focused: .clear,
            pressed: .clear,
            pressedContentOpacity: ControlPalette.pressedContentOpacity
        ),
        chrome: SurfaceChrome(),
        clipsToBounds: false,
        animation: .default
    )

    /// Filled destructive surface — the `.borderedProminent` + `.destructive`
    /// combination only. macOS fills with the system red (`#FF3B30`), not a
    /// muted brick, and casts the same neutral 1pt ambient shadow every other
    /// control does; the previous `offset (0,16) / spread 10` painted a
    /// detached red slab a control-height below the button.
    public static let destructive = ButtonSurfaceStyle.destructiveFilled(palette: .darkStandard)

    public static func destructiveFilled(palette: ControlPalette) -> ButtonSurfaceStyle {
        let red = Color.red
        return ButtonSurfaceStyle(
            cornerRadius: MacOSControlMetrics.Button.regularCornerRadius,
            palette: SurfacePalette(
                idle: red,
                hovered: ControlPalette.lightened(red, by: 0.08),
                focused: ControlPalette.lightened(red, by: 0.08),
                pressed: ControlPalette.darkened(red, by: 0.12),
                disabledBackground: palette.quaternaryFill,
                disabledForeground: palette.disabledLabel,
                disabledBorder: palette.quaternaryLabel
            ),
            chrome: palette.buttonChrome(focusTint: red),
            clipsToBounds: true,
            animation: .default
        )
    }

    /// Standard bordered-button ramp, appearance-resolved.
    public static func bordered(palette: ControlPalette) -> ButtonSurfaceStyle {
        ButtonSurfaceStyle(
            cornerRadius: MacOSControlMetrics.Button.regularCornerRadius,
            palette: palette.borderedButtonPalette,
            chrome: palette.buttonChrome(focusTint: .accentColor),
            clipsToBounds: true,
            animation: .default
        )
    }

    public static let defaultPalette = ControlPalette.darkStandard.borderedButtonPalette
}
