public struct ListStyle: Sendable, Equatable {
    enum Kind: Sendable, Equatable {
        case automatic
        case bordered
        case carousel
        case elliptical
        case plain
        case grouped
        case inset
        case insetGrouped
        case sidebar
    }

    let kind: Kind
    private let alternatesRowBackgrounds: Bool?

    private init(kind: Kind, alternatesRowBackgrounds: Bool? = nil) {
        self.kind = kind
        self.alternatesRowBackgrounds = alternatesRowBackgrounds
    }

    public static let automatic = ListStyle(kind: .automatic)
    public static let bordered = ListStyle(kind: .bordered)
    public static let carousel = ListStyle(kind: .carousel)
    public static let elliptical = ListStyle(kind: .elliptical)
    public static let plain = ListStyle(kind: .plain)
    public static let grouped = ListStyle(kind: .grouped)
    public static let inset = ListStyle(kind: .inset)
    public static let insetGrouped = ListStyle(kind: .insetGrouped)
    public static let sidebar = ListStyle(kind: .sidebar)

    static func inset(alternatesRowBackgrounds: Bool?) -> ListStyle {
        ListStyle(kind: .inset, alternatesRowBackgrounds: alternatesRowBackgrounds)
    }

    public static func == (lhs: ListStyle, rhs: ListStyle) -> Bool {
        lhs.kind == rhs.kind
    }

    /// A list''s body, hairline and alternating stripe are appearance
    /// roles. They used to be dark literals, so `.preferredColorScheme(
    /// .light)` produced light rows on a dark list body.
    func retainedChrome(palette: ControlPalette) -> RetainedListChrome {
        switch kind {
        case .automatic, .plain:
            // macOS plain/automatic lists inset their row content from the
            // list edge and never draw a row shorter than the standard row
            // box (MacOSControlMetrics.List.plainRowHeight).
            //
            // The body is `textBackgroundColor`, and it is the *view's* body,
            // not the rows': an NSTableView shorter than its scroll view
            // still paints its background down to the clip view's bottom
            // edge. With no background at all the chrome stopped at the last
            // row and everything below it was bare window — a short list in a
            // tall slot read as a list floating over a hole rather than as a
            // table with room left in it.
            return RetainedListChrome(
                defaultSpacing: 0,
                padding: EdgeInsets(
                    top: 0,
                    leading: MacOSControlMetrics.List.contentInset,
                    bottom: 0,
                    trailing: MacOSControlMetrics.List.contentInset
                ),
                backgroundColor: palette.controlBackground,
                rowMinHeight: MacOSControlMetrics.List.plainRowHeight,
                drawsRowSeparators: true,
                separatorLeadingInset: 0
            )
        case .bordered:
            return RetainedListChrome(
                defaultSpacing: 0,
                padding: EdgeInsets(top: 0, leading: 0, bottom: 0, trailing: 0),
                backgroundColor: nil,
                borderColor: palette.controlBorder,
                borderWidth: 1,
                cornerRadius: 6
            )
        case .carousel, .elliptical:
            return RetainedListChrome(
                defaultSpacing: 6,
                padding: EdgeInsets(top: 8, leading: 8, bottom: 8, trailing: 8),
                backgroundColor: palette.controlBackground,
                borderColor: palette.separator,
                borderWidth: 1,
                cornerRadius: MacOSControlMetrics.Radius.lg
            )
        case .grouped:
            return RetainedListChrome(
                defaultSpacing: 8,
                padding: EdgeInsets(top: 8, leading: 0, bottom: 8, trailing: 0),
                backgroundColor: palette.controlBackground,
                borderColor: palette.separator,
                borderWidth: 1,
                cornerRadius: MacOSControlMetrics.Radius.lg
            )
        case .inset:
            // `.inset` had no body at all: no fill, no ring, no corners, no
            // rule between rows, and a 6pt gap holding the rows apart. Four
            // strings floated on the window background, which is the one
            // thing an *inset table* is not — the inset in the name is the
            // row content's inset from the body's edge, so without a body
            // there is nothing for it to be inset from.
            //
            // The body is the same `textBackgroundColor` card the plain and
            // automatic styles paint, closed with the 6pt radius and hairline
            // a `.bordered` list gets, and the rows are ruled and inset into
            // it. The card fills the list's own frame rather than sitting in
            // a margin inside it: an NSTableView's background is the *clip
            // view's* background, and a list that left a gutter around itself
            // would show window backdrop inside its own scroll bounds.
            //
            // Stripes and rules are alternatives, not a stack: AppKit's
            // alternating row colours *are* the row boundary, and a table
            // that drew both reads as a spreadsheet.
            let stripes = alternatesRowBackgrounds == true
            return RetainedListChrome(
                defaultSpacing: 0,
                padding: EdgeInsets(
                    top: MacOSControlMetrics.List.insetVerticalInset,
                    leading: MacOSControlMetrics.List.contentInset,
                    bottom: MacOSControlMetrics.List.insetVerticalInset,
                    trailing: MacOSControlMetrics.List.contentInset
                ),
                backgroundColor: palette.controlBackground,
                borderColor: palette.separator,
                borderWidth: 1,
                cornerRadius: MacOSControlMetrics.List.insetCornerRadius,
                alternatesRowBackgrounds: stripes,
                alternatingRowBackgroundColor: palette.quinaryFill,
                rowMinHeight: MacOSControlMetrics.List.plainRowHeight,
                drawsRowSeparators: !stripes,
                separatorLeadingInset: 0
            )
        case .insetGrouped:
            return RetainedListChrome(
                defaultSpacing: 8,
                padding: EdgeInsets(top: 10, leading: 12, bottom: 10, trailing: 12),
                backgroundColor: palette.controlBackground,
                borderColor: palette.separator,
                borderWidth: 1,
                cornerRadius: MacOSControlMetrics.Radius.lg
            )
        case .sidebar:
            return RetainedListChrome(
                defaultSpacing: 4,
                padding: EdgeInsets(top: 6, leading: 6, bottom: 6, trailing: 6),
                backgroundColor: palette.controlBackground,
                borderColor: .clear,
                borderWidth: 0,
                cornerRadius: 10,
                rowMinHeight: MacOSControlMetrics.List.sidebarRowHeight
            )
        }
    }
}
