struct RetainedListChrome: Sendable, Equatable {
    var defaultSpacing: Double = 0
    var padding: EdgeInsets = .zero
    var backgroundColor: Color? = nil
    var borderColor: Color = .clear
    var borderWidth: Double = 0
    var cornerRadius: Double = 0
    var alternatesRowBackgrounds: Bool = false
    var alternatingRowBackgroundColor: Color? = nil
    /// Minimum height every row in this style gets, before its own
    /// content or a `defaultMinListRowHeight` environment value.
    /// Anchored to `MacOSControlMetrics.List`.
    var rowMinHeight: Double = 0
    /// Whether this style draws a hairline rule *between* rows.
    ///
    /// The retained model had no way to express a separator at all, so the
    /// default list style rendered as bare strings on the window
    /// background. macOS's inset/plain lists rule between every pair of
    /// adjacent rows — never after the last one, and never under a
    /// selected row.
    var drawsRowSeparators: Bool = false
    /// Leading inset of the rule from the list's content edge. macOS
    /// starts the rule at the row's text, not at the list's frame.
    var separatorLeadingInset: Double = 0
}
public struct ScrollIndicatorVisibility: Sendable, Equatable {
    enum Kind: Sendable, Equatable {
        case automatic
        case visible
        case hidden
        case never
    }

    let kind: Kind

    private init(kind: Kind) {
        self.kind = kind
    }

    public static let automatic = ScrollIndicatorVisibility(kind: .automatic)
    public static let visible = ScrollIndicatorVisibility(kind: .visible)
    public static let hidden = ScrollIndicatorVisibility(kind: .hidden)
    public static let never = ScrollIndicatorVisibility(kind: .never)

    var showsRetainedScrollIndicator: Bool {
        switch kind {
        case .automatic, .visible:
            return true
        case .hidden, .never:
            return false
        }
    }

    /// Whether the scroller behaves as a macOS *overlay* scroller — invisible
    /// at rest, revealed by scrolling, faded out afterwards.
    ///
    /// `.automatic` is the macOS default and is therefore an overlay.
    /// `.visible` is the app asking for the scroller to be on screen, which is
    /// the "Show scroll bars: Always" appearance: a persistent bar.
    var usesRetainedOverlayScrollIndicator: Bool {
        switch kind {
        case .automatic, .hidden, .never:
            return true
        case .visible:
            return false
        }
    }
}
