            retainedVisualEffectDescription:
                "\(retainedVisualEffectDescription).rotationEffect(angle:\(angle.radians),anchor:\(anchor.x),\(anchor.y))",
            operations: _baseOperations + [.rotationEffect(angle.radians)]
        )
