        return EmptyVisualEffect(
            retainedVisualEffectDescription:
                "\(retainedVisualEffectDescription).rotation3DEffect(angle:\(angle.radians),axis:\(axis.x),\(axis.y),\(axis.z),anchor3D:\(anchor.x),\(anchor.y),\(anchor.z))",
