@MainActor
func composeComponent(
    from views: [AnyView],
    context: ViewBuildContext,
    fallbackLayout: ViewLayoutMode = .absolute,
    isHitTestVisible: Bool = false
) -> Component {
    makeCompositionComponent(
        from: views, context: context, fallbackLayout: fallbackLayout,
        isHitTestVisible: isHitTestVisible, allowsStructuralChildren: false)
}

/// Only pure composition producers opt into child expansion. Other callers
/// retain their existing single-node boundary, including the one-child case.
@MainActor
func composeStructuralComponent(from views: [AnyView], context: ViewBuildContext) -> Component {
    makeCompositionComponent(
        from: views, context: context, fallbackLayout: .absolute,
        isHitTestVisible: false, allowsStructuralChildren: true)
}

@MainActor
private func makeCompositionComponent(
    from views: [AnyView],
    context: ViewBuildContext,
    fallbackLayout: ViewLayoutMode,
    isHitTestVisible: Bool,
    allowsStructuralChildren: Bool
) -> Component {
    guard let expandedViews = materializedDeferredViewList(views, context: context) else {
        return rejectedRetainedViewComponent()
    }
    guard
        let views = viewIdentityOccurrences(
            expandedViews, lazyAttribution: context.viewIdentity.lazyList,
            descriptorAttribution: context.viewIdentity.descriptorComponent, coordinator: context.stateMountCoordinator),
        context.viewIdentity.lazyList?.admission.isCurrent != false,
        context.viewIdentity.descriptorComponent?.canConstruct != false
    else { return rejectedRetainedViewComponent() }
    if views.count == 1, let view = views.first {
        let component = view.makeComponent(context: context)
        return allowsStructuralChildren ? component : component.asSingleNode()
    }

    let makeNode: @MainActor (RetainedViewRuntime) -> ViewNode = { runtime in
        Controls.panel(
            layoutMode: fallbackLayout,
            isHitTestVisible: isHitTestVisible,
            children: views.map { $0.makeComponent(context: context).makeNode(runtime: runtime) }
        )
    }
    guard allowsStructuralChildren else { return Component(makeViewNode: makeNode) }
    return Component(
        makeViewNode: makeNode,
        appendStructuralChildren: { runtime, nodes in
            for view in views {
                view.makeComponent(context: context).appendChildNodes(runtime: runtime, to: &nodes)
            }
        }
    )
}
extension HorizontalAlignment {
    func resolved(for layoutDirection: LayoutDirection) -> HorizontalAlignment {
        switch (self, layoutDirection) {
        case (.leading, .rightToLeft):
            return .trailing
        case (.trailing, .rightToLeft):
            return .leading
        case (.leading, .leftToRight), (.center, _), (.trailing, .leftToRight), (.custom, _):
            return self
        }
    }

    var stackAlignment: StackCrossAlignment {
        stackAlignment(layoutDirection: .leftToRight)
    }

    func stackAlignment(layoutDirection: LayoutDirection) -> StackCrossAlignment {
        switch resolved(for: layoutDirection) {
        case .leading:
            return .leading
        case .center:
            return .center
        case .trailing:
            return .trailing
        case .custom(let name, _):
            return .customHorizontal("custom:\(name)")
        }
    }

    var textAlignment: TextHorizontalAlignment {
        textAlignment(layoutDirection: .leftToRight)
    }

    func textAlignment(layoutDirection: LayoutDirection) -> TextHorizontalAlignment {
        switch resolved(for: layoutDirection) {
        case .leading:
            return .leading
        case .center:
            return .center
        case .trailing:
            return .trailing
        case .custom:
            return .center
        }
    }
}
