extension SwiftWindowsCore.Color {
    public enum RGBColorSpace: Sendable, Equatable, Hashable {
        case sRGB
        case sRGBLinear
        case displayP3
    }

    public init(red: Double, green: Double, blue: Double, opacity: Double = 1.0) {
        self.init(red: Float(red), green: Float(green), blue: Float(blue), alpha: Float(opacity))
    }

    public init(_ colorSpace: RGBColorSpace = .sRGB, red: Double, green: Double, blue: Double, opacity: Double = 1.0) {
        let components = RetainedColorSpaceConversion.encodedSRGB(
            from: colorSpace, red: red, green: green, blue: blue)
        self.init(
            red: RetainedColorSpaceConversion.storedFloat(components.red),
            green: RetainedColorSpaceConversion.storedFloat(components.green),
            blue: RetainedColorSpaceConversion.storedFloat(components.blue),
            alpha: Float(opacity)
        )
    }

    public init(white: Double, opacity: Double = 1.0) {
        let channel = Float(clampedUnitInterval(white))
        self.init(red: channel, green: channel, blue: channel, alpha: Float(clampedUnitInterval(opacity)))
    }

    public init(_ colorSpace: RGBColorSpace = .sRGB, white: Double, opacity: Double = 1.0) {
        let channel = Float(retainedColorChannel(clampedUnitInterval(white), colorSpace: colorSpace))
        self.init(red: channel, green: channel, blue: channel, alpha: Float(clampedUnitInterval(opacity)))
    }

    public init(_ name: String, bundle: Bundle? = nil) {
        self.init(ColorResource(name: name, bundle: bundle ?? .main))
    }

    public init(_ resource: ColorResource) {
        self = resolvedColorResource(resource) ?? SwiftWindowsCore.Color.accentColor
    }

    public func opacity(_ value: Double) -> SwiftWindowsCore.Color {
        let components = rgba
        return SwiftWindowsCore.Color(red: components.0, green: components.1, blue: components.2, alpha: Float(value))
    }

    public nonisolated func retainedWithMultipliedOpacity(_ opacity: Double) -> SwiftWindowsCore.Color {
        let clampedOpacity = Float(min(max(opacity, 0), 1))
        let components = rgba
        return SwiftWindowsCore.Color(
            red: components.0,
            green: components.1,
            blue: components.2,
            alpha: components.3 * clampedOpacity
        )
    }

    /// Which rung of the `labelColor` hierarchy this colour *is*, if any.
    ///
    /// The semantic colours are sentinels: `Color.primary` and friends are
    /// the dark-appearance rungs of `LabelHierarchy`, and recognising one
    /// here is what lets a flat RGBA struct still carry an appearance.
    /// Everything else — a literal the app wrote, an accent, an image
    /// sample — is returned untouched.
    nonisolated var labelHierarchyLevel: HierarchicalShapeStyle.Level? {
        let (red, green, blue, alpha) = rgba
        guard red == 1, green == 1, blue == 1 else {
            return nil
        }
        switch alpha {
        case LabelHierarchy.primaryAlpha:
            return .primary
        case LabelHierarchy.secondaryAlpha, LabelHierarchy.increasedContrastSecondaryAlpha:
            return .secondary
        case LabelHierarchy.tertiaryAlpha, LabelHierarchy.increasedContrastTertiaryAlpha:
            return .tertiary
        case LabelHierarchy.quaternaryAlpha:
            return .quaternary
        case LabelHierarchy.quinaryAlpha:
            return .quinary
        default:
            return nil
        }
    }

    /// Resolves a semantic label colour for one appearance and contrast.
    ///
    /// Before this existed, `resolvedForVisualEnvironment` took contrast
    /// and background prominence but never the colour scheme, so
    /// `Color.primary` was a literal white and light mode was not merely
    /// unwired — it could not be expressed. The appearance now selects the
    /// base (white or black) and the contrast selects the rung, both out of
    /// the same `ControlPalette` the control chrome reads.
    public nonisolated func resolvedForVisualEnvironment(
        colorScheme: ColorScheme,
        contrast: ColorSchemeContrast,
        backgroundProminence: BackgroundProminence,
        systemColors: HighContrastSystemColors? = nil
    ) -> SwiftWindowsCore.Color {
        // `.increased` background prominence is AppKit's "this sits on a
        // filled selection" signal: secondary text stops being secondary.
        let effectiveLevel: HierarchicalShapeStyle.Level?
        if backgroundProminence == .increased, labelHierarchyLevel == .secondary {
            effectiveLevel = .primary
        } else {
            effectiveLevel = labelHierarchyLevel
        }
        guard let effectiveLevel else {
            // Not a rung of the label ladder. The other appearance-aware
            // family is the system colour table, whose statics hold the
            // light value: `Text("Degraded").foregroundColor(.orange)` on a
            // dark window used to paint `#FF9500`, the light-appearance
            // orange, because nothing on this path knew there was a second
            // one. Everything else — a literal the app wrote, an image
            // sample, a palette tone — still passes through untouched.
            guard colorScheme == .dark else {
                return self
            }
            return SystemColorPalette.darkVariant(of: self) ?? self
        }

        let palette = ControlPalette.resolve(
            colorScheme: colorScheme,
            contrast: contrast,
            systemColors: systemColors
        )
        if backgroundProminence == .increased {
            // An emphasised selection is the *same* saturated accent fill in
            // both appearances, so the ladder over it is built on
            // `alternateSelectedControlTextColor` — white — and not on the
            // appearance's base. Resolving against `palette.label` put
            // near-black text on the blue selection fill in light mode: the
            // promotion above fixed the rung and left the base wrong.
            let base = palette.selectedContentLabel
            switch effectiveLevel {
            case .primary:
                return base
            case .secondary:
                return base.retainedWithMultipliedOpacity(Double(LabelHierarchy.secondaryAlpha))
            case .tertiary:
                return base.retainedWithMultipliedOpacity(Double(LabelHierarchy.tertiaryAlpha))
            case .quaternary:
                return base.retainedWithMultipliedOpacity(Double(LabelHierarchy.quaternaryAlpha))
            case .quinary:
                return base.retainedWithMultipliedOpacity(Double(LabelHierarchy.quinaryAlpha))
            }
        }
        switch effectiveLevel {
        case .primary:
            return palette.label
        case .secondary:
            return palette.secondaryLabel
        case .tertiary:
            return palette.tertiaryLabel
        case .quaternary:
            return palette.quaternaryLabel
        case .quinary:
            // AppKit has no fifth published rung; SwiftUI's quinary sits
            // just under quaternary.
            return palette.quaternaryLabel.retainedWithMultipliedOpacity(0.6)
        }
    }

    /// Resolves a colour that is about to be painted as a *background*.
    ///
    /// One rung reads differently on the way to a fill: `.quaternary`. As a
    /// label it is the fourth text rung and that stays untouched. But the
    /// idiomatic use of `.background(.quaternary)` is a *bar*: the scrim that
    /// closes a list with an inspector or status strip.
    ///
    /// **A bar is never brighter than the list it closes in the dark
    /// appearance, or darker than it in the light one.** Drawn as a wash the
    /// rung fails that in whichever appearance it is not tuned for: the light
    /// black wash landed the bar *below* the page it closed, and once the
    /// dark rung moved to 0.30 for legibility the same maths lifted a dark
    /// footer well above the table above it — a bar brighter than its own
    /// content, which reads as a second window pinned to the bottom.
    ///
    /// It resolves to the page tone in **both** appearances now, and the
    /// hairline above it carries the edge. One rule, not two, and it is the
    /// same rule Finder's status bar and Xcode's debug bar follow. Pinned in
    /// docs/MacOSDesignParity.md and `MacOSDesignParityTests`.
    public nonisolated func resolvedForBackgroundVisualEnvironment(
        colorScheme: ColorScheme,
        contrast: ColorSchemeContrast,
        backgroundProminence: BackgroundProminence,
        systemColors: HighContrastSystemColors? = nil
    ) -> SwiftWindowsCore.Color {
        if backgroundProminence != .increased, labelHierarchyLevel == .quaternary {
            return ControlPalette.resolve(
                colorScheme: colorScheme,
                contrast: contrast,
                systemColors: systemColors
            ).windowBackground
        }
        return resolvedForVisualEnvironment(
            colorScheme: colorScheme,
            contrast: contrast,
            backgroundProminence: backgroundProminence,
            systemColors: systemColors
        )
    }
}
extension ForegroundStyle {
    func retainedWithOpacity(_ opacity: Double) -> ForegroundStyle {
