private func resolvedColorResource(_ resource: ColorResource) -> SwiftWindowsCore.Color? {
    parsedHexColor(resource.name)
}
private func parsedHexColor(_ value: String) -> SwiftWindowsCore.Color? {
    var hex = value.trimmingCharacters(in: .whitespacesAndNewlines)
    if hex.hasPrefix("#") {
        hex.removeFirst()
    } else if hex.lowercased().hasPrefix("0x") {
        hex.removeFirst(2)
    }
    hex.removeAll { $0 == "_" || $0 == "-" }

    let expanded: String
    switch hex.count {
    case 3, 4:
        expanded = hex.map { "\($0)\($0)" }.joined()
    case 6, 8:
        expanded = hex
    default:
        return nil
    }

    guard expanded.allSatisfy(\.isHexDigit),
        let rawValue = UInt32(expanded, radix: 16)
    else {
        return nil
    }

    let red: UInt32
    let green: UInt32
    let blue: UInt32
    let alpha: UInt32
    if expanded.count == 8 {
        red = (rawValue >> 24) & 0xFF
        green = (rawValue >> 16) & 0xFF
        blue = (rawValue >> 8) & 0xFF
        alpha = rawValue & 0xFF
    } else {
        red = (rawValue >> 16) & 0xFF
        green = (rawValue >> 8) & 0xFF
        blue = rawValue & 0xFF
        alpha = 0xFF
    }

    return SwiftWindowsCore.Color(
        red: Float(red) / 255.0,
        green: Float(green) / 255.0,
        blue: Float(blue) / 255.0,
        alpha: Float(alpha) / 255.0
    )
}
private func resolvedStyleColor(from style: ForegroundStyle) -> Color {
    switch style {
    case .color(let color):
        return color
    case .linearGradient(let gradient):
        return gradient.startColor
    case .radialGradient(let gradient):
        return gradient.stops.first?.color ?? .clear
    case .conicGradient(let gradient):
        return gradient.stops.first?.color ?? .clear
    case .materialFill(let tint, _):
        return tint
    }
}
private func resolvedBorderFill(from style: ForegroundStyle) -> (color: Color, gradient: LinearGradient?) {
    switch style {
    case .color(let color):
        return (color, nil)
    case .linearGradient(let gradient):
        return (gradient.startColor, gradient)
    case .radialGradient(let gradient):
        return (gradient.stops.first?.color ?? .clear, nil)
    case .conicGradient(let gradient):
        return (gradient.stops.first?.color ?? .clear, nil)
    case .materialFill(let tint, _):
        return (tint, nil)
    }
}
extension SwiftWindowsGraphics.LinearGradient {
    public init(_ gradient: WinSwiftUI.LinearGradient) {
        let axis = gradient.axis
        let isReversed =
            axis == .horizontal
            ? gradient.endPoint.x < gradient.startPoint.x
            : gradient.endPoint.y < gradient.startPoint.y
        let stops =
            isReversed
            ? gradient.stops.reversed().map {
                GradientStop(color: $0.color, position: 1 - $0.position)
            }
            : gradient.stops
        self.init(stops: stops, axis: axis, reversesAuthoredStops: isReversed)
    }
}
extension SwiftWindowsGraphics.RadialGradient {
    public init(_ gradient: WinSwiftUI.RadialGradient) {
        let center = Point(x: gradient.center.x, y: gradient.center.y)
        self.init(
            center: center,
            radius: gradient.endRadius,
            stops: gradient.stops,
            startRadius: gradient.startRadius,
            centerIsUnitPoint: true)
    }
}
extension SwiftWindowsGraphics.ConicGradient {
    public init(_ gradient: WinSwiftUI.AngularGradient) {
        let center = Point(x: gradient.center.x, y: gradient.center.y)
        let angle = gradient.startAngle.radians
        let authoredEndAngle = gradient.endAngle.radians
        self.init(
            center: center,
            angle: angle,
            stops: gradient.stops,
            endAngle: authoredEndAngle == angle ? nil : authoredEndAngle,
            centerIsUnitPoint: true)
    }
}
extension EdgeInsets {
    public init() {
        self.init(top: 0, leading: 0, bottom: 0, trailing: 0)
    }

    static func all(_ value: Double) -> EdgeInsets {
        EdgeInsets(top: value, leading: value, bottom: value, trailing: value)
    }
}
@MainActor
private func applyToolbarBackgroundStyle(
    to node: ViewNode,
    color: Color?,
    gradient: GradientType?,
    bars: [ToolbarItemPlacement] = []
) {
    if node.isToolbarContainer, retainedToolbarMatches(node.toolbarPlacementTags, bars: bars) {
        node.backgroundColor = color
        node.backgroundGradient = gradient
    }

    for child in node.children {
        applyToolbarBackgroundStyle(to: child, color: color, gradient: gradient, bars: bars)
    }
}
@MainActor
private func applyToolbarVisibility(to node: ViewNode, visibility: Visibility, bars: [ToolbarItemPlacement] = []) {
    if node.isToolbarContainer, retainedToolbarMatches(node.toolbarPlacementTags, bars: bars) {
        switch visibility {
        case .hidden:
            node.isHidden = true
        case .visible:
            node.isHidden = false
        case .automatic:
            break
        }
    }

    for child in node.children {
        applyToolbarVisibility(to: child, visibility: visibility, bars: bars)
    }
}
@MainActor
private func retainedListSeparatorDefaultColor() -> Color {
    ControlPalette.darkStandard.separator
}
@MainActor
private func retainedListSeparatorNode(tint: Color? = nil) -> ViewNode {
    // A rule has thickness on one axis and no extent of its own on the
    // other; the 16pt stub never reached the row's width.
    let node = Controls.panel(
        preferredSize: Size(width: 0, height: 1),
        backgroundColor: tint ?? retainedListSeparatorDefaultColor(),
        isHitTestVisible: false
    )
    node.layoutFillAxes = .horizontalOnly
    return node
}
@MainActor
private func applyRetainedListSeparatorTint(to node: ViewNode, tint: RetainedListSeparatorTint) {
    node.listRowSeparatorTint = tint

    guard let separator = node.listRowSeparator, separator.visibility == .visible else {
        return
    }

    let color = tint.color ?? retainedListSeparatorDefaultColor()
    var visibleSeparatorIndex = 0
    if separator.edges.contains(.top), node.children.indices.contains(visibleSeparatorIndex) {
        if tint.edges.contains(.top) {
            node.children[visibleSeparatorIndex].backgroundColor = color
        }
        visibleSeparatorIndex += 1
    }

    if separator.edges.contains(.bottom), let bottomSeparator = node.children.last, tint.edges.contains(.bottom) {
        bottomSeparator.backgroundColor = color
    }
}
@MainActor
private func applyRetainedListSectionSeparatorTint(to node: ViewNode, tint: RetainedListSeparatorTint) {
    node.listSectionSeparatorTint = tint

    guard let separator = node.listSectionSeparator, separator.visibility == .visible else {
        return
    }

    let color = tint.color ?? retainedListSeparatorDefaultColor()
    var visibleSeparatorIndex = 0
    if separator.edges.contains(.top), node.children.indices.contains(visibleSeparatorIndex) {
        if tint.edges.contains(.top) {
            node.children[visibleSeparatorIndex].backgroundColor = color
        }
        visibleSeparatorIndex += 1
    }

    if separator.edges.contains(.bottom), let bottomSeparator = node.children.last, tint.edges.contains(.bottom) {
        bottomSeparator.backgroundColor = color
    }
}
@MainActor
private func applyRetainedListItemTint(to node: ViewNode, tint: RetainedListItemTint) {
    node.listItemTint = tint
    guard let color = tint.color else {
        return
    }

    applyRetainedListItemTintColor(to: node, color: color)
}
@MainActor
private func applyRetainedListItemTintColor(to node: ViewNode, color: Color) {
    if node.text != nil {
        var textStyle = node.textStyle
        textStyle.color = color
        node.textStyle = textStyle
    }

    for child in node.children where child.listItemTint == nil {
        applyRetainedListItemTintColor(to: child, color: color)
    }
}
@MainActor
private func applyToolbarColorScheme(
    to node: ViewNode,
    colorScheme: ColorScheme?,
    bars: [ToolbarItemPlacement] = []
) {
    guard let colorScheme else {
        return
    }

    if node.isToolbarContainer, retainedToolbarMatches(node.toolbarPlacementTags, bars: bars) {
        if colorScheme == .light {
            if node.backgroundGradient == nil {
                node.backgroundColor = Color(red: 0.957, green: 0.957, blue: 0.957, alpha: 0.95)
            }
            node.borderColor = Color(red: 0.157, green: 0.157, blue: 0.157, alpha: 0.16)
            applyToolbarForegroundColor(to: node, color: Color(red: 0.107, green: 0.107, blue: 0.107, alpha: 1))
        } else {
            if node.backgroundGradient == nil {
                node.backgroundColor = Color(red: 0.107, green: 0.107, blue: 0.107, alpha: 0.92)
            }
            node.borderColor = Color(red: 0.977, green: 0.977, blue: 0.977, alpha: 0.08)
            applyToolbarForegroundColor(to: node, color: Color(red: 0.966, green: 0.966, blue: 0.966, alpha: 1))
        }
        return
    }

    for child in node.children {
        applyToolbarColorScheme(to: child, colorScheme: colorScheme, bars: bars)
    }
}
@MainActor
private func applyToolbarForegroundColor(to node: ViewNode, color: Color) {
    if node.text != nil {
        var style = node.textStyle
        style.color = color
        node.textStyle = style
    }

    for child in node.children {
        applyToolbarForegroundColor(to: child, color: color)
    }
}
@MainActor
private func applyToolbarRoleChrome(to node: ViewNode, role: ToolbarRole) {
    if node.isToolbarContainer {
        if role == .editor {
            node.cornerRadius = 6
            node.borderWidth = 1
            node.borderColor = Color(red: 0.44, green: 0.60, blue: 0.86, alpha: 0.30)
            node.shadowColor = Color(red: 0.059, green: 0.059, blue: 0.059, alpha: 0.18)
            node.shadowOffset = Point(x: 0, y: 1)
            node.shadowSpread = 6
        } else if role == .browser {
            node.cornerRadius = 10
            node.borderWidth = 1
            node.borderColor = Color(red: 0.977, green: 0.977, blue: 0.977, alpha: 0.12)
            node.shadowColor = Color(red: 0.03, green: 0.03, blue: 0.03, alpha: 0.24)
            node.shadowOffset = Point(x: 0, y: 2)
            node.shadowSpread = 10
        } else if role == .navigationStack {
            node.cornerRadius = 0
            node.borderWidth = 1
            node.borderColor = Color(red: 0.977, green: 0.977, blue: 0.977, alpha: 0.10)
            node.shadowColor = .clear
            node.shadowOffset = .zero
            node.shadowSpread = 0
        }
    }

    for child in node.children {
        applyToolbarRoleChrome(to: child, role: role)
    }
}
@MainActor
private func applyToolbarTitleDisplayMode(to node: ViewNode, mode: ToolbarTitleDisplayMode) {
    if node.isToolbarContainer, case .stack(var layout) = node.layoutMode {
        if mode == .large {
            layout.padding = EdgeInsets(top: 12, leading: 12, bottom: 12, trailing: 12)
        } else if mode == .inlineLarge {
            layout.padding = EdgeInsets(top: 8, leading: 10, bottom: 8, trailing: 10)
        } else {
            layout.padding = EdgeInsets(top: 6, leading: 8, bottom: 6, trailing: 8)
        }
        node.layoutMode = .stack(layout)
    }

    for child in node.children {
        applyToolbarTitleDisplayMode(to: child, mode: mode)
    }
}
extension Alignment {
    func frameOrigin(
        for childSize: Size,
        in containerSize: Size,
        layoutDirection: LayoutDirection = .leftToRight
    ) -> Point {
        let x: Double
        switch horizontal.resolved(for: layoutDirection) {
        case .leading:
            x = 0
        case .center:
            x = max(0, (containerSize.width - childSize.width) * 0.5)
        case .trailing:
            x = max(0, containerSize.width - childSize.width)
        case .custom:
            x = max(0, (containerSize.width - childSize.width) * 0.5)
        }

        let y: Double
        switch vertical {
        case .top, .firstTextBaseline:
            y = 0
        case .center:
            y = max(0, (containerSize.height - childSize.height) * 0.5)
        case .bottom, .lastTextBaseline:
            y = max(0, containerSize.height - childSize.height)
        case .custom:
            y = 0
        }

        return Point(x: x, y: y)
    }
}
private func normalizedFrameMinimum(_ value: Double?) -> Double {
    guard let value, value.isFinite else {
        return 0
    }

    return max(0, value)
}
private func normalizedFrameMaximum(_ value: Double?, minimum: Double) -> Double {
    guard let value else {
        return .infinity
    }

    guard value.isFinite else {
        return .infinity
    }

    return max(minimum, value)
}
private func normalizedFrameIdeal(_ value: Double?) -> Double? {
    guard let value, value.isFinite else {
        return nil
    }

    return max(0, value)
}
private func normalizedContainerRelativeLength(_ value: Double) -> Double {
    guard value.isFinite else {
        return 0
    }

    return max(0, value)
}
private func containerRelativeSpanLength(
    availableLength: Double,
    count: Int,
    span: Int,
    spacing: Double
) -> Double {
    let resolvedCount = max(1, count)
    let resolvedSpan = min(max(1, span), resolvedCount)
    let resolvedSpacing = max(0, spacing)
    let totalSpacing = Double(resolvedCount - 1) * resolvedSpacing
    let slotLength = max(0, availableLength - totalSpacing) / Double(resolvedCount)
    return slotLength * Double(resolvedSpan) + Double(resolvedSpan - 1) * resolvedSpacing
}
private func aspectRatioPreferredSize(
    baseSize: Size,
    requestedAspectRatio: Double?,
    contentMode: ContentMode
) -> Size {
    let nativeRatio = baseSize.width > 0 && baseSize.height > 0 ? baseSize.width / baseSize.height : 1
    let requestedRatio = requestedAspectRatio ?? nativeRatio
    let ratio = requestedRatio.isFinite && requestedRatio > 0 ? requestedRatio : 1
    let baseRatio = nativeRatio.isFinite && nativeRatio > 0 ? nativeRatio : 1

    switch contentMode {
    case .fit:
        return ratio >= baseRatio
            ? Size(width: baseSize.width, height: baseSize.width / ratio)
            : Size(width: baseSize.height * ratio, height: baseSize.height)
    case .fill:
        return ratio >= baseRatio
            ? Size(width: baseSize.height * ratio, height: baseSize.height)
            : Size(width: baseSize.width, height: baseSize.width / ratio)
    }
}
/// Shared lowering for Image's typed fit modifier and the generic View path.
/// The old preference is only an ideal fallback; retained measurement resolves
/// finite fit from the live proposal. Keep the original centered stack for
/// declined proposals; only an admitted measurement selects fit placement.
@MainActor
func retainedAspectFitComponent(child: Component, aspectRatio: Double?) -> Component {
    Component { runtime in
        let childNode = child.makeNode(runtime: runtime)
        let preferredSize = aspectRatioPreferredSize(
            baseSize: childNode.intrinsicContentSize(), requestedAspectRatio: aspectRatio, contentMode: .fit)
        let root = Controls.stackPanel(
            preferredSize: preferredSize,
            stackLayout: .vertical(padding: .zero, alignment: .center, mainAlignment: .center),
            isHitTestVisible: false, children: [childNode])
        root.aspectFitLayout = RetainedAspectFitLayout(aspectRatio: aspectRatio)
        return root
    }
}

@MainActor
func rejectedRetainedViewNode() -> ViewNode {
    let node = Controls.panel(preferredSize: .zero, isHitTestVisible: false)
    node.markRejectedRetainedSource()
    return node
}

@MainActor
func rejectedRetainedViewComponent() -> Component {
    Component { _ in rejectedRetainedViewNode() }
}

@MainActor
protocol MountedOnChangeUpdate: AnyObject {
    var owner: StateMountOwner { get }
    func commit()
    func deliver()
}

private final class OnChangeDeliveryIdentity {}

/// A box distinguishes an unobserved mount from an observed Optional.none.
/// Values retain their ordinary reference semantics; this is not a deep copy.
@MainActor
private final class OnChangeObservedValue<Value> {
    let value: Value

    init(_ value: Value) { self.value = value }
}

@MainActor
private final class OnChangeObservation<Value> {
    var value: OnChangeObservedValue<Value>?
    var delivery: OnChangeDeliveryIdentity?
}

/// A build owns its proposed value and latest action. The mount owns only its
/// comparison baseline, so neither a discarded build nor an escaped old action
/// can move the next comparison to another occurrence's value.
@MainActor
private final class OnChangeUpdate<Value: Equatable>: MountedOnChangeUpdate {
    let owner: StateMountOwner
    private let cell: MountedStateCell<OnChangeObservation<Value>>
    private let value: OnChangeObservedValue<Value>
    private let initial: Bool
    private let action: (Value, Value) -> Void
    private let delivery = OnChangeDeliveryIdentity()
    private var previous: OnChangeObservedValue<Value>?
    private var didCommit = false
    private var didDeliver = false

    init(
        owner: StateMountOwner, cell: MountedStateCell<OnChangeObservation<Value>>,
        value: Value, initial: Bool, action: @escaping (Value, Value) -> Void
    ) {
        self.owner = owner
        self.cell = cell
        self.value = OnChangeObservedValue(value)
        self.initial = initial
        self.action = action
    }

    func commit() {
        guard !didCommit, owner.isLive, cell.isWritable else { return }
        didCommit = true
        let observation = cell.readValue()
        // Pin the displaced Value before replacing storage. Its destructor
        // must not reenter while this adopted batch is still being published.
        previous = observation.value
        observation.delivery = delivery
        observation.value = value
    }

    private var isCurrent: Bool {
        owner.isLive && cell.isWritable && cell.readValue().delivery === delivery
    }

    func deliver() {
        guard didCommit, !didDeliver, isCurrent else { return }
        // Equality is application code too. Claim the delivery before calling
        // it, and recheck ownership if it closes or replaces this occurrence.
        didDeliver = true
        if let previous {
            let changed = previous.value != value.value
            guard isCurrent else { return }
            if !changed {
                // Keep the existing value policy when Equatable ignores a
                // payload field. Reentry must not restore over a newer token.
                // Both boxes remain pinned until this batch finishes cleanup.
                cell.readValue().value = previous
                return
            }
            action(previous.value, value.value)
        } else if initial, isCurrent {
            action(value.value, value.value)
        }
    }
}

@MainActor
private func stageOnChangeObservation<Value: Equatable>(
    value: Value, initial: Bool, action: @escaping (Value, Value) -> Void, context: ViewBuildContext,
    lazyGroup: RetainedLazyListGroupID? = nil, descriptorGroup: RetainedDescriptorGroupID? = nil
) {
    let type = ObjectIdentifier(OnChangeObservation<Value>.self)
    if let attribution = context.viewIdentity.lazyList {
        guard attribution.admission.isCurrent, let group = lazyGroup else { return }
        context.stateMountCoordinator?.stageOnChange(
            at: context.retainedViewIdentity.appending(.view(type)),
            attribution: attribution, kind: .onChange, group: group,
            seedObservation: { OnChangeObservation<Value>() },
            makeUpdate: { owner, cell in
                guard attribution.admission.isCurrent else { return nil }
                return OnChangeUpdate(owner: owner, cell: cell, value: value, initial: initial, action: action)
            })
        return
    }
    if let attribution = context.viewIdentity.descriptorComponent {
        guard attribution.canConstruct, let group = descriptorGroup else { return }
        context.stateMountCoordinator?.stageOnChange(
            at: context.retainedViewIdentity.appending(.view(type)),
            descriptorAttribution: attribution, kind: .onChange, group: group,
            seedObservation: { OnChangeObservation<Value>() },
            makeUpdate: { owner, cell in
                guard attribution.canConstruct else { return nil }
                return OnChangeUpdate(owner: owner, cell: cell, value: value, initial: initial, action: action)
            })
        return
    }
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        seedObservation: { OnChangeObservation<Value>() },
        makeUpdate: { owner, cell in
            OnChangeUpdate(owner: owner, cell: cell, value: value, initial: initial, action: action)
        })
}

private enum PreferenceChangeObservationOwner<Key: PreferenceKey> {}

@MainActor
private func stagePreferenceChangeObservation<Key: PreferenceKey>(
    in node: ViewNode, key: Key.Type,
    action: @escaping (Key.Value) -> Void, context: ViewBuildContext
) where Key.Value: Equatable {
    let type = ObjectIdentifier(PreferenceChangeObservationOwner<Key>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        seedObservation: { OnChangeObservation<Key.Value>() },
        makeUpdate: { owner, cell in
            let preferenceValue = retainedPreferenceValueIfPresent(in: node, key: key)
            let resolvedValue = preferenceValue ?? Key.defaultValue
            return OnChangeUpdate(
                owner: owner, cell: cell, value: resolvedValue, initial: preferenceValue != nil,
                action: { _, newValue in action(newValue) })
        })
}

@MainActor
private func stageLazyPreferenceChangeObservation<Key: PreferenceKey>(
    in nodes: [ViewNode], key: Key.Type,
    action: @escaping (Key.Value) -> Void, context: ViewBuildContext,
    attribution: LazyListViewAttribution, group: RetainedLazyListGroupID
) where Key.Value: Equatable {
    guard attribution.admission.isCurrent else { return }
    let type = ObjectIdentifier(PreferenceChangeObservationOwner<Key>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        attribution: attribution, kind: .onPreferenceChange, group: group,
        seedObservation: { OnChangeObservation<Key.Value>() },
        makeUpdate: { owner, cell in
            guard let lookup = attribution.admission.beginLookup() else { return nil }
            let admission = PreferenceConstructionAdmission.lazy(attribution.admission, lookup: lookup)
            guard
                let preference = retainedAdmittedPreferenceValue(in: nodes, key: key, admission: admission),
                admission.isCurrent
            else { return nil }
            // An explicitly emitted default is still a present preference.
            // Absence retains the ordinary missing-preference baseline policy.
            let value = preference.hasValue ? preference.value : Key.defaultValue
            guard admission.isCurrent else { return nil }
            return OnChangeUpdate(
                owner: owner, cell: cell, value: value, initial: preference.hasValue,
                action: { _, newValue in action(newValue) })
        })
}

@MainActor
private func stageDescriptorPreferenceChangeObservation<Key: PreferenceKey>(
    in nodes: [ViewNode], key: Key.Type,
    action: @escaping (Key.Value) -> Void, context: ViewBuildContext,
    attribution: RetainedDescriptorComponentAttribution, group: RetainedDescriptorGroupID
) where Key.Value: Equatable {
    guard attribution.canConstruct else { return }
    let type = ObjectIdentifier(PreferenceChangeObservationOwner<Key>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        descriptorAttribution: attribution, kind: .onPreferenceChange, group: group,
        seedObservation: { OnChangeObservation<Key.Value>() },
        makeUpdate: { owner, cell in
            guard let lookup = context.stateMountCoordinator?.descriptorLookupReceipt(for: attribution) else {
                return nil
            }
            let admission = PreferenceConstructionAdmission.descriptor(attribution, lookup: lookup)
            guard
                let preference = retainedAdmittedPreferenceValue(in: nodes, key: key, admission: admission),
                admission.isCurrent
            else { return nil }
            let value = preference.hasValue ? preference.value : Key.defaultValue
            guard admission.isCurrent else { return nil }
            return OnChangeUpdate(
                owner: owner, cell: cell, value: value, initial: preference.hasValue,
                action: { _, newValue in action(newValue) })
        })
}

@MainActor
private func observingChanges<Value: Equatable>(
    in component: Component, value: Value, initial: Bool,
    action: @escaping (Value, Value) -> Void, context: ViewBuildContext
) -> Component {
    if let attribution = context.viewIdentity.lazyList {
        return lazyListSyntheticComponent(
            in: component, context: context, attribution: attribution, kind: .observation,
            prepare: { group in
                stageOnChangeObservation(
                    value: value, initial: initial, action: action, context: context, lazyGroup: group)
            })
    }
    if let attribution = context.viewIdentity.descriptorComponent {
        return descriptorSyntheticComponent(
            in: component, context: context, attribution: attribution, kind: .observation,
            prepare: { group in
                stageOnChangeObservation(
                    value: value, initial: initial, action: action, context: context, descriptorGroup: group)
            })
    }
    // A raw Component has no mounted lifetime or adoption receipt. In
    // particular it must not borrow history from another runtime or callsite.
    guard context.stateMountCoordinator != nil else { return component }
    let makeNode: @MainActor (RetainedViewRuntime) -> ViewNode = { runtime in
        stageOnChangeObservation(value: value, initial: initial, action: action, context: context)
        return component.makeNode(runtime: runtime)
    }
    guard component.hasStructuralChildren else { return Component(makeViewNode: makeNode) }
    return Component(
        makeViewNode: makeNode,
        appendStructuralChildren: { runtime, nodes in
            stageOnChangeObservation(value: value, initial: initial, action: action, context: context)
            component.appendChildNodes(runtime: runtime, to: &nodes)
        })
}

/// Register the modifier before its observer work and retain its exact
/// structural outputs. An empty append closes a proposal without inventing a
/// node; only the native structural adoption can later accept that proposal.
@MainActor
func lazyListSyntheticComponent(
    in component: Component, context: ViewBuildContext, attribution: LazyListViewAttribution,
    kind: RetainedLazyListContributionKind,
    prepare: @escaping @MainActor (RetainedLazyListGroupID) -> Void = { _ in },
    stage: @escaping @MainActor ([ViewNode], RetainedViewRuntime, RetainedLazyListGroupID) -> Void = { _, _, _ in }
) -> Component {
    @MainActor
    func begin() -> RetainedLazyListGroupID? {
        guard context.stateMountCoordinator != nil, attribution.admission.isCurrent,
            let group = attribution.native.registerGroup(kind: kind), attribution.admission.isCurrent
        else { return nil }
        prepare(group)
        return attribution.admission.isCurrent ? group : nil
    }

    @MainActor
    func finish(_ nodes: [ViewNode], runtime: RetainedViewRuntime, group: RetainedLazyListGroupID) -> Bool {
        guard attribution.admission.isCurrent else { return false }
        stage(nodes, runtime, group)
        guard attribution.admission.isCurrent else { return false }
        for node in nodes {
            guard attribution.native.recordSourceOutput(node, group: group) != nil,
                attribution.admission.isCurrent
            else { return false }
        }
        return attribution.native.closeGroup(group) != nil && attribution.admission.isCurrent
    }

    let makeNode: @MainActor (RetainedViewRuntime) -> ViewNode = { runtime in
        guard let group = begin() else {
            return rejectedRetainedViewNode()
        }
        let node = component.makeNode(runtime: runtime)
        guard finish([node], runtime: runtime, group: group) else {
            return rejectedRetainedViewNode()
        }
        return node
    }
    guard component.hasStructuralChildren else { return Component(makeViewNode: makeNode) }
    return Component(
        makeViewNode: makeNode,
        appendStructuralChildren: { runtime, nodes in
            guard let group = begin() else {
                nodes.append(rejectedRetainedViewNode())
                return
            }
            var outputs: [ViewNode] = []
            component.appendChildNodes(runtime: runtime, to: &outputs)
            guard finish(outputs, runtime: runtime, group: group) else {
                nodes.append(rejectedRetainedViewNode())
                return
            }
            nodes.append(contentsOf: outputs)
        })
}

/// Root and ordinary subtree components also need exact effect groups when a
/// build contains a managed List. These records carry no logical row receipt.
@MainActor
func descriptorSyntheticComponent(
    in component: Component, context: ViewBuildContext, attribution: RetainedDescriptorComponentAttribution,
    kind: RetainedLazyListContributionKind,
    prepare: @escaping @MainActor (RetainedDescriptorGroupID) -> Void = { _ in },
    stage: @escaping @MainActor ([ViewNode], RetainedViewRuntime, RetainedDescriptorGroupID) -> Void = { _, _, _ in }
) -> Component {
    @MainActor
    func begin() -> RetainedDescriptorGroupID? {
        guard context.stateMountCoordinator != nil, attribution.canConstruct,
            let group = attribution.registerGroup(kind: kind), attribution.canConstruct
        else { return nil }
        prepare(group)
        return attribution.canConstruct ? group : nil
    }

    @MainActor
    func finish(_ nodes: [ViewNode], runtime: RetainedViewRuntime, group: RetainedDescriptorGroupID) -> Bool {
        guard attribution.canConstruct else { return false }
        stage(nodes, runtime, group)
        guard attribution.canConstruct else { return false }
        for node in nodes {
            guard attribution.recordSourceOutput(node, group: group), attribution.canConstruct else { return false }
        }
        return attribution.closeGroup(group) != nil && attribution.canConstruct
    }

    let makeNode: @MainActor (RetainedViewRuntime) -> ViewNode = { runtime in
        guard let group = begin() else {
            return rejectedRetainedViewNode()
        }
        let node = component.makeNode(runtime: runtime)
        guard finish([node], runtime: runtime, group: group) else {
            return rejectedRetainedViewNode()
        }
        return node
    }
    guard component.hasStructuralChildren else { return Component(makeViewNode: makeNode) }
    return Component(
        makeViewNode: makeNode,
        appendStructuralChildren: { runtime, nodes in
            guard let group = begin() else {
                nodes.append(rejectedRetainedViewNode())
                return
            }
            var outputs: [ViewNode] = []
            component.appendChildNodes(runtime: runtime, to: &outputs)
            guard finish(outputs, runtime: runtime, group: group) else {
                nodes.append(rejectedRetainedViewNode())
                return
            }
            nodes.append(contentsOf: outputs)
        })
}

@MainActor
private final class TaskIDObservation<Value> {
    let mount = RetainedTaskMountToken()
    var value: OnChangeObservedValue<Value>?
    var delivery: OnChangeDeliveryIdentity?
}

private enum TaskIDObservationOwner<Value> {}

/// A task ID is compared only after its materialized occurrence and actual
/// retained target have been adopted. The mount keeps its comparison value;
/// the retained node owns the current action and independently cancelable run.
@MainActor
private final class TaskIDUpdate<Value: Equatable>: MountedOnChangeUpdate {
    let owner: StateMountOwner
    private let cell: MountedStateCell<TaskIDObservation<Value>>
    private let value: OnChangeObservedValue<Value>
    private let delivery: OnChangeDeliveryIdentity
    private let declaration: RetainedTaskDeclaration
    private var previous: OnChangeObservedValue<Value>?
    private var didCommit = false
    private var didDeliver = false

    init(
        owner: StateMountOwner, cell: MountedStateCell<TaskIDObservation<Value>>,
        value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
        source: ViewNode, runtime: RetainedViewRuntime
    ) {
        self.owner = owner
        self.cell = cell
        self.value = OnChangeObservedValue(value)
        let delivery = OnChangeDeliveryIdentity()
        self.delivery = delivery
        let declaration = RetainedTaskDeclaration(
            mount: cell.readValue().mount, priority: priority, action: action,
            isMember: { [weak owner, weak cell] in
                // Only committed cells enter this predicate. Check the live
                // owner first, without entering provisional identity lookup.
                owner?.isLive == true && cell?.isWritable == true
            },
            isCurrentProposal: { [weak owner, weak cell] in
                guard owner?.isLive == true, let cell, cell.isWritable else { return false }
                return cell.readValue().delivery === delivery
            })
        self.declaration = declaration
        declaration.stage(on: source, in: runtime)

        let existingOnAppearWithNode = source.onAppearWithNode
        source.onAppearWithNode = { [weak declaration] node in
            existingOnAppearWithNode?(node)
            declaration?.appear(on: node)
        }
        let existingOnDisappearWithNode = source.onDisappearWithNode
        source.onDisappearWithNode = { [weak declaration] node in
            existingOnDisappearWithNode?(node)
            declaration?.disappear(from: node)
        }
    }

    init?(
        owner: StateMountOwner, cell: MountedStateCell<TaskIDObservation<Value>>,
        value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
        groupSources: [ViewNode], runtime: RetainedViewRuntime,
        attribution: LazyListViewAttribution, group: RetainedLazyListGroupID
    ) {
        guard !groupSources.isEmpty, attribution.admission.isCurrent else { return nil }
        self.owner = owner
        self.cell = cell
        self.value = OnChangeObservedValue(value)
        let delivery = OnChangeDeliveryIdentity()
        self.delivery = delivery
        let declaration = RetainedTaskDeclaration(
            mount: cell.readValue().mount, priority: priority, action: action,
            isMember: { [weak owner, weak cell] in
                owner?.isLive == true && cell?.isWritable == true
            },
            isCurrentProposal: { [weak owner, weak cell] in
                guard owner?.isLive == true, let cell, cell.isWritable else { return false }
                return cell.readValue().delivery === delivery
            })
        self.declaration = declaration
        guard
            declaration.stage(
                groupSources: groupSources, in: runtime, lazyAttribution: attribution.native, group: group),
            attribution.admission.isCurrent
        else { return nil }

        // One declaration owns the group. Each real output keeps its ordinary
        // hook chain; no output is selected as another output's task target.
        for source in groupSources {
            guard attribution.admission.isCurrent else { return nil }
            let existingOnAppearWithNode = source.onAppearWithNode
            source.onAppearWithNode = { [weak declaration] node in
                existingOnAppearWithNode?(node)
                declaration?.appear(on: node)
            }
            let existingOnDisappearWithNode = source.onDisappearWithNode
            source.onDisappearWithNode = { [weak declaration] node in
                existingOnDisappearWithNode?(node)
                declaration?.disappear(from: node)
            }
        }
        guard attribution.admission.isCurrent else { return nil }
    }

    init?(
        owner: StateMountOwner, cell: MountedStateCell<TaskIDObservation<Value>>,
        value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
        groupSources: [ViewNode], runtime: RetainedViewRuntime,
        descriptorAttribution: RetainedDescriptorComponentAttribution, group: RetainedDescriptorGroupID
    ) {
        guard !groupSources.isEmpty, descriptorAttribution.canConstruct else { return nil }
        self.owner = owner
        self.cell = cell
        self.value = OnChangeObservedValue(value)
        let delivery = OnChangeDeliveryIdentity()
        self.delivery = delivery
        let declaration = RetainedTaskDeclaration(
            mount: cell.readValue().mount, priority: priority, action: action,
            isMember: { [weak owner, weak cell] in
                owner?.isLive == true && cell?.isWritable == true
            },
            isCurrentProposal: { [weak owner, weak cell] in
                guard owner?.isLive == true, let cell, cell.isWritable else { return false }
                return cell.readValue().delivery === delivery
            })
        self.declaration = declaration
        guard
            declaration.stage(
                groupSources: groupSources, in: runtime, descriptorAttribution: descriptorAttribution, group: group),
            descriptorAttribution.canConstruct
        else { return nil }
        for source in groupSources {
            guard descriptorAttribution.canConstruct else { return nil }
            let existingOnAppearWithNode = source.onAppearWithNode
            source.onAppearWithNode = { [weak declaration] node in
                existingOnAppearWithNode?(node)
                declaration?.appear(on: node)
            }
            let existingOnDisappearWithNode = source.onDisappearWithNode
            source.onDisappearWithNode = { [weak declaration] node in
                existingOnDisappearWithNode?(node)
                declaration?.disappear(from: node)
            }
        }
        guard descriptorAttribution.canConstruct else { return nil }
    }

    func commit() {
        guard !didCommit, owner.isLive, cell.isWritable, declaration.canCommit else { return }
        didCommit = true
        let observation = cell.readValue()
        previous = observation.value
        observation.delivery = delivery
        observation.value = value
    }

    private var isCurrent: Bool {
        owner.isLive && cell.isWritable && cell.readValue().delivery === delivery
    }

    func deliver() {
        guard didCommit, !didDeliver, isCurrent else { return }
        didDeliver = true
        var restart = false
        if let previous {
            restart = previous.value != value.value
            guard isCurrent else { return }
            if !restart {
                // Equality may deliberately ignore a reference payload. Keep
                // the previous box without restoring over a newer proposal.
                cell.readValue().value = previous
            }
        }
        guard isCurrent else { return }
        declaration.deliver(restart: restart)
    }
}

@MainActor
private func stageTaskIDObservation<Value: Equatable>(
    value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
    on node: ViewNode, in runtime: RetainedViewRuntime, context: ViewBuildContext
) {
    let type = ObjectIdentifier(TaskIDObservationOwner<Value>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        seedObservation: { TaskIDObservation<Value>() },
        makeUpdate: { owner, cell in
            TaskIDUpdate(
                owner: owner, cell: cell, value: value, priority: priority, action: action,
                source: node, runtime: runtime)
        })
}

@MainActor
private func stageLazyTaskIDObservation<Value: Equatable>(
    value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
    on nodes: [ViewNode], in runtime: RetainedViewRuntime, context: ViewBuildContext,
    attribution: LazyListViewAttribution, group: RetainedLazyListGroupID
) {
    // Empty structural output owns no task observation, declaration or launch
    // owner. A later nonempty materialization establishes a fresh task mount.
    guard !nodes.isEmpty, attribution.admission.isCurrent else { return }
    let type = ObjectIdentifier(TaskIDObservationOwner<Value>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        attribution: attribution, kind: .taskID, group: group,
        seedObservation: { TaskIDObservation<Value>() },
        makeUpdate: { owner, cell in
            guard attribution.admission.isCurrent else { return nil }
            return TaskIDUpdate(
                owner: owner, cell: cell, value: value, priority: priority, action: action,
                groupSources: nodes, runtime: runtime, attribution: attribution, group: group)
        })
}

@MainActor
private func stageDescriptorTaskIDObservation<Value: Equatable>(
    value: Value, priority: TaskPriority, action: @escaping @Sendable () async -> Void,
    on nodes: [ViewNode], in runtime: RetainedViewRuntime, context: ViewBuildContext,
    attribution: RetainedDescriptorComponentAttribution, group: RetainedDescriptorGroupID
) {
    guard !nodes.isEmpty, attribution.canConstruct else { return }
    let type = ObjectIdentifier(TaskIDObservationOwner<Value>.self)
    context.stateMountCoordinator?.stageOnChange(
        at: context.retainedViewIdentity.appending(.view(type)),
        descriptorAttribution: attribution, kind: .taskID, group: group,
        seedObservation: { TaskIDObservation<Value>() },
        makeUpdate: { owner, cell in
            guard attribution.canConstruct else { return nil }
            return TaskIDUpdate(
                owner: owner, cell: cell, value: value, priority: priority, action: action,
                groupSources: nodes, runtime: runtime, descriptorAttribution: attribution, group: group)
        })
}

@MainActor
private final class OnReceiveSubscription<Source: Publisher> {
    private let publisher: Source
    private let action: @MainActor (Source.Output) -> Void
    private var cancellable: AnyCancellable?

    init(
        publisher: Source,
        action: @escaping @MainActor (Source.Output) -> Void
    ) {
        self.publisher = publisher
        self.action = action
    }

    func subscribeIfNeeded() {
        guard cancellable == nil else {
            return
        }

        cancellable = publisher.sink(receiveValue: action)
    }

    func cancel() {
        cancellable?.cancel()
        cancellable = nil
    }
}
private func retainedPreferenceIdentifier<Key: PreferenceKey>(_ key: Key.Type) -> ObjectIdentifier {
    ObjectIdentifier(key)
}
private func retainedLayoutValueIdentifier<Key: LayoutValueKey>(_ key: Key.Type) -> ObjectIdentifier {
    ObjectIdentifier(key)
}
func retainedContainerValuesIdentifier() -> ObjectIdentifier {
    ObjectIdentifier(ContainerValues.self)
}
@MainActor
private func retainedAnchor(for node: ViewNode, source: Anchor<Rect>.Source, context: ViewBuildContext) -> Anchor<Rect>
{
    switch source.kind {
    case .bounds:
        var size = node.intrinsicContentSize()
        if size.width <= 0 && size.height <= 0 {
            size = context.canvasSize
        }
        return Anchor(Rect(origin: .zero, size: size))
    case .rect(let rect):
        return Anchor(rect)
    }
}
@MainActor
private func setRetainedPreference<Key: PreferenceKey>(
    _ key: Key.Type,
    value: Key.Value,
    on node: ViewNode
) {
    node.retainedPreferenceValues[retainedPreferenceIdentifier(key)] = value
}
@MainActor
private func retainedPreferenceValueIfPresent<Key: PreferenceKey>(
    in node: ViewNode,
    key: Key.Type
) -> Key.Value? {
    let identifier = retainedPreferenceIdentifier(key)
    var resolvedValue = Key.defaultValue
    var hasValue = false

    if let directValue = node.retainedPreferenceValues[identifier] as? Key.Value {
        Key.reduce(value: &resolvedValue) {
            directValue
        }
        hasValue = true
    }

    guard !node.retainedPreferenceTransformBoundaries.contains(identifier) else {
        return hasValue ? resolvedValue : nil
    }

    for child in node.children {
        guard let childValue = retainedPreferenceValueIfPresent(in: child, key: key) else {
            continue
        }

        Key.reduce(value: &resolvedValue) {
            childValue
        }
        hasValue = true
    }

    return hasValue ? resolvedValue : nil
}

private struct AdmittedPreferenceValue<Value> {
    let value: Value
    let hasValue: Bool
}

@MainActor
private enum PreferenceConstructionAdmission {
    case lazy(LazyListResolutionReceipt, lookup: LazyListLookupReceipt)
    case descriptor(RetainedDescriptorComponentAttribution, lookup: LazyListLookupReceipt)

    var isCurrent: Bool {
        switch self {
        case .lazy(let receipt, let lookup): receipt.isCurrent && lookup.isCurrent
        case .descriptor(let attribution, let lookup): attribution.canConstruct && lookup.isCurrent
        }
    }
}

/// A reducer and a default getter are authored code. Keep the original
/// admission across each call so reentry cannot continue reducing a retired
/// physical contribution or install its value in another build.
@MainActor
@inline(never)
private func retainedAdmittedPreferenceValue<Key: PreferenceKey>(
    in node: ViewNode, key: Key.Type, admission: PreferenceConstructionAdmission
) -> AdmittedPreferenceValue<Key.Value>? {
    guard admission.isCurrent else { return nil }
    let identifier = retainedPreferenceIdentifier(key)
    var value = Key.defaultValue
    guard admission.isCurrent else { return nil }
    var hasValue = false
    if let directValue = node.retainedPreferenceValues[identifier] as? Key.Value {
        guard admission.isCurrent else { return nil }
        Key.reduce(value: &value) { directValue }
        guard admission.isCurrent else { return nil }
        hasValue = true
    }
    guard admission.isCurrent else { return nil }
    if node.retainedPreferenceTransformBoundaries.contains(identifier) {
        return AdmittedPreferenceValue(value: value, hasValue: hasValue)
    }
    let children = node.children
    for child in children {
        guard let childValue = retainedAdmittedPreferenceValue(in: child, key: key, admission: admission),
            admission.isCurrent
        else { return nil }
        if childValue.hasValue {
            Key.reduce(value: &value) { childValue.value }
            guard admission.isCurrent else { return nil }
            hasValue = true
        }
    }
    return admission.isCurrent ? AdmittedPreferenceValue(value: value, hasValue: hasValue) : nil
}

@MainActor
@inline(never)
private func retainedAdmittedPreferenceValue<Key: PreferenceKey>(
    in nodes: [ViewNode], key: Key.Type, admission: PreferenceConstructionAdmission
) -> AdmittedPreferenceValue<Key.Value>? {
    guard admission.isCurrent else { return nil }
    if nodes.count == 1, let node = nodes.first {
        return retainedAdmittedPreferenceValue(in: node, key: key, admission: admission)
    }
    var value = Key.defaultValue
    guard admission.isCurrent else { return nil }
    var hasValue = false
    for node in nodes {
        guard let nodeValue = retainedAdmittedPreferenceValue(in: node, key: key, admission: admission),
            admission.isCurrent
        else { return nil }
        if nodeValue.hasValue {
            Key.reduce(value: &value) { nodeValue.value }
            guard admission.isCurrent else { return nil }
            hasValue = true
        }
    }
    return admission.isCurrent ? AdmittedPreferenceValue(value: value, hasValue: hasValue) : nil
}
@MainActor
private func retainedPreferenceValue<Key: PreferenceKey>(
    in node: ViewNode,
    key: Key.Type
) -> Key.Value {
    retainedPreferenceValueIfPresent(in: node, key: key) ?? Key.defaultValue
}
private func mergedPresentationChrome(
    _ base: RetainedPresentationChrome,
    applying override: RetainedPresentationChrome
) -> RetainedPresentationChrome {
    var result = base
    if override.hasBackgroundOverride {
        result.hasBackgroundOverride = true
        result.backgroundColor = override.backgroundColor
        result.backgroundGradient = override.backgroundGradient
    }
    if override.hasCornerRadiusOverride {
        result.hasCornerRadiusOverride = true
        result.cornerRadius = override.cornerRadius
    }
    if override.hasDragIndicatorOverride {
        result.hasDragIndicatorOverride = true
        result.showsDragIndicator = override.showsDragIndicator
    }
    if override.hasDetentsOverride {
        result.hasDetentsOverride = true
        result.detents = override.detents
        result.selectedDetent = override.selectedDetent
    }
    if override.hasInteractiveDismissDisabledOverride {
        result.hasInteractiveDismissDisabledOverride = true
        result.interactiveDismissDisabled = override.interactiveDismissDisabled
    }
    if override.hasBackgroundInteractionOverride {
        result.hasBackgroundInteractionOverride = true
        result.allowsBackgroundInteraction = override.allowsBackgroundInteraction
    }
    if override.hasContentInteractionOverride {
        result.hasContentInteractionOverride = true
        result.contentInteraction = override.contentInteraction
    }
    if override.hasCompactAdaptationOverride {
        result.hasCompactAdaptationOverride = true
        result.horizontalCompactAdaptation = override.horizontalCompactAdaptation
        result.verticalCompactAdaptation = override.verticalCompactAdaptation
    }
    if override.hasIsModalOverride {
        result.hasIsModalOverride = true
        result.isModal = override.isModal
    }
    return result
}
@MainActor
private func retainedPresentationChrome(in node: ViewNode) -> RetainedPresentationChrome {
    var chrome = RetainedPresentationChrome.empty
    for child in node.children {
        chrome = mergedPresentationChrome(chrome, applying: retainedPresentationChrome(in: child))
    }
    return mergedPresentationChrome(chrome, applying: node.presentationChrome)
}
private func retainedPresentationDetentSortKey(_ detent: RetainedPresentationDetent) -> (Int, Double) {
    switch detent {
    case .medium:
        return (0, 0)
    case .fraction(let fraction):
        return (1, fraction.isFinite ? fraction : 0)
    case .height(let height):
        return (2, height.isFinite ? height : 0)
    case .large:
        return (3, 0)
    }
}
private func retainedPresentationDetentPrecedes(
    _ lhs: RetainedPresentationDetent,
    _ rhs: RetainedPresentationDetent
) -> Bool {
    let lhsKey = retainedPresentationDetentSortKey(lhs)
    let rhsKey = retainedPresentationDetentSortKey(rhs)
    if lhsKey.0 != rhsKey.0 {
        return lhsKey.0 < rhsKey.0
    }
    return lhsKey.1 < rhsKey.1
}
private func retainedPresentationDetents(from detents: Set<PresentationDetent>) -> [RetainedPresentationDetent] {
    detents.map(\.retainedDetent).sorted(by: retainedPresentationDetentPrecedes)
}
private func clampedPresentationFraction(_ fraction: Double) -> Double {
    guard fraction.isFinite else {
        return 0
    }
    return min(1, max(0, fraction))
}
private func retainedPresentationHeight(
    chrome: RetainedPresentationChrome,
    boundsSize: Size
) -> Double? {
    guard chrome.hasDetentsOverride else {
        return nil
    }

    let detents = chrome.detents
    let selectedDetent =
        chrome.selectedDetent.flatMap { selected in
            detents.isEmpty || detents.contains(selected) ? selected : nil
        } ?? detents.first
    guard let selectedDetent else {
        return nil
    }

    let availableHeight = max(0, boundsSize.height - 48)
    let targetHeight: Double
    switch selectedDetent {
    case .medium:
        targetHeight = availableHeight * 0.5
    case .large:
        targetHeight = availableHeight
    case .height(let height):
        targetHeight = height.isFinite ? max(0, height) : 0
    case .fraction(let fraction):
        targetHeight = availableHeight * clampedPresentationFraction(fraction)
    }

    return min(availableHeight, targetHeight)
}
private func normalizedPresentationCornerRadius(_ value: Double?, defaultValue: Double) -> Double {
    guard let value, value.isFinite else {
        return defaultValue
    }
    return max(0, value)
}
@MainActor
private func retainedPresentationDragIndicatorNode() -> ViewNode {
    let handle = Controls.panel(
        preferredSize: Size(width: 36, height: 5),
        backgroundColor: Color(red: 0.968, green: 0.968, blue: 0.968, alpha: 0.44),
        cornerRadius: 2.5,
        isHitTestVisible: false
    )
    return Controls.stackPanel(
        stackLayout: .horizontal(spacing: 0, alignment: .center, mainAlignment: .center),
        isHitTestVisible: false,
        children: [handle]
    )
}
@MainActor
private func retainedPresentationChildren(
    contentNode: ViewNode,
    chrome: RetainedPresentationChrome,
    palette: ControlPalette,
    wrapsScrollingContent: Bool = false
) -> [ViewNode] {
    let presentedContentNode =
        wrapsScrollingContent && chrome.contentInteraction == .scrolls
        ? retainedPresentationScrollContentNode(contentNode, palette: palette)
        : contentNode
    return chrome.showsDragIndicator
        ? [retainedPresentationDragIndicatorNode(), presentedContentNode]
        : [presentedContentNode]
}
@MainActor
private func retainedPresentationScrollContentNode(_ contentNode: ViewNode, palette: ControlPalette) -> ViewNode {
    let scrollNode = Controls.scrollPanel(
        axis: .vertical,
        layoutPriority: 1,
        stackLayout: .vertical(
            spacing: 0,
            padding: .zero,
            alignment: .stretch,
            mainAlignment: .start
        ),
        scrollStep: ViewNode.defaultScrollLineHeight,
        scrollIndicatorColor: palette.scrollerKnob,
        scrollIndicatorHoverColor: palette.scrollerKnobHovered,
        scrollIndicatorActiveColor: palette.scrollerKnobActive,
        scrollIndicatorThickness: MacOSControlMetrics.Scroller.overlayThumbThickness,
        scrollIndicatorInsets: EdgeInsets(
            top: MacOSControlMetrics.Scroller.overlayInset,
            leading: MacOSControlMetrics.Scroller.overlayInset,
            bottom: MacOSControlMetrics.Scroller.overlayInset,
            trailing: MacOSControlMetrics.Scroller.overlayInset
        ),
        scrollIndicatorAutoHides: true,
        isHitTestVisible: true,
        children: [contentNode]
    )
    scrollNode.nodeTag = "presentation-content-scrolls"
    return scrollNode
}
/// Chains an Escape-key dismissal onto every node in the subtree, preserving
/// any existing key-down handler, mirroring the Menu overlay's behavior.
@MainActor
private func attachRetainedEscapeDismiss(
    to node: ViewNode,
    within presentation: ViewNode? = nil,
    dismiss: @escaping @MainActor () -> Void
) {
    let existingKeyDown = node.onKeyDown
    node.onKeyDown = { event in
        // Capture ownership before the nested handler dismisses itself: an
        // inner modal may remove its trait while restoring focus, but that
        // one Escape must never cascade into its outer presentation.
        let ownsModalEvent: Bool
        if let presentation, presentation.isModalPresentationScope {
            var ancestor: ViewNode? = node
            while let candidate = ancestor, !candidate.isModalPresentationScope {
                ancestor = candidate.parent
            }
            ownsModalEvent = ancestor === presentation
        } else {
            ownsModalEvent = true
        }
        existingKeyDown?(event)
        if event.key == .escape, ownsModalEvent {
            dismiss()
        }
    }

    for child in node.children {
        attachRetainedEscapeDismiss(to: child, within: presentation, dismiss: dismiss)
    }
}
/// Runs `restoreFocus` before any existing activation handler in the subtree
/// so activating a presentation's action buttons also returns keyboard focus
/// to the control that was focused when the presentation appeared.
@MainActor
private func attachRetainedPresentationFocusRestore(
    to node: ViewNode,
    restoreFocus: @escaping @MainActor () -> Void
) {
    if let activate = node.onActivate {
        node.onActivate = {
            restoreFocus()
            activate()
        }
    }

    for child in node.children {
        attachRetainedPresentationFocusRestore(to: child, restoreFocus: restoreFocus)
    }
}
@MainActor
private func retainedPresentationNode(_ node: ViewNode, isWithin ancestor: ViewNode) -> Bool {
    var current: ViewNode? = node
    while let currentNode = current {
        if currentNode === ancestor {
            return true
        }
        current = currentNode.parent
    }
    return false
}
@MainActor
private func retainedFirstFocusableNode(in node: ViewNode) -> ViewNode? {
    if node.isFocusable {
        return node
    }
    for child in node.children {
        if let match = retainedFirstFocusableNode(in: child) {
            return match
        }
    }
    return nil
}
/// Restores keyboard focus after an overlay dismissal: back to the node that
/// was focused when the presentation appeared, or — when that node is gone or
/// nothing was focused — to the first focusable control in the base content
/// (approximating SwiftUI's restoration to the presentation's source control).
@MainActor
private func retainedRestorePresentationFocus(
    runtime: RetainedViewRuntime,
    focusedAtPresentation: ViewNode?,
    baseNode: ViewNode,
    overlayNode: ViewNode
) {
    // Dismissal restores focus before the presentation binding changes.
    // Release this presentation's modal scope first so its source control
    // (or an underlying nested modal) is eligible immediately.
    overlayNode.accessibilityTraits.subtract(.isModal)

    if let focusedAtPresentation,
        !retainedPresentationNode(focusedAtPresentation, isWithin: overlayNode),
        retainedPresentationNode(focusedAtPresentation, isWithin: runtime.root)
    {
        runtime.requestFocus(focusedAtPresentation)
        return
    }

    if let fallback = retainedFirstFocusableNode(in: baseNode) {
        runtime.requestFocus(fallback)
    }
}
/// Absolute origin of `node` within the window, approximated by walking the
/// parent chain. Ancestor scroll offsets are not accounted for, matching the
/// retained menu's attachment approximation.
@MainActor
private func retainedPresentationAbsoluteOrigin(of node: ViewNode) -> Point {
    var origin = Point.zero
    var current: ViewNode? = node
    while let currentNode = current {
        origin = Point(
            x: origin.x + currentNode.frame.origin.x,
            y: origin.y + currentNode.frame.origin.y
        )
        current = currentNode.parent
    }
    return origin
}
/// Frame that makes an overlay scrim cover the full canvas, no matter where
/// the presentation's root sits in the window.
@MainActor
private func retainedPresentationCanvasScrimFrame(root: ViewNode, canvasSize: Size) -> Rect {
    let rootOrigin = retainedPresentationAbsoluteOrigin(of: root)
    return Rect(
        x: -rootOrigin.x,
        y: -rootOrigin.y,
        width: canvasSize.width,
        height: canvasSize.height
    )
}
@MainActor
private func retainedUnpresentedSheet(base: Component) -> Component {
    Component { runtime in
        let baseNode = base.makeNode(runtime: runtime)
        // Keep the same host and base-child slot as a presented sheet. Returning
        // the bare base would replace its retained identity on every toggle.
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode]
        )
        root.onLayout = { bounds in
            let baseFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != baseFrame { baseNode.frame = baseFrame }
        }
        return root
    }
}
@MainActor
private func retainedCurrentSheetRoot(_ authoredRoot: ViewNode, in runtime: RetainedViewRuntime) -> ViewNode? {
    if retainedPresentationNode(authoredRoot, isWithin: runtime.root) { return authoredRoot }
    guard let identity = authoredRoot.retainedViewIdentity else { return nil }
    var pending = [runtime.root]
    while let node = pending.popLast() {
        if node.retainedViewIdentity == identity { return node }
        pending.append(contentsOf: node.children)
    }
    return nil
}
@MainActor
private func retainedSheetPresentation(
    base: Component,
    sheet: Component,
    context: ViewBuildContext,
    onInteractiveDismiss: @escaping @MainActor () -> Void,
    hostedDismissal: PresentationDismissHandle? = nil
) -> Component {
    Component { runtime in
        let baseNode = base.makeNode(runtime: runtime)
        let sheetContentNode = sheet.makeNode(runtime: runtime)
        let presentationChrome = retainedPresentationChrome(in: sheetContentNode)
        let allowsBackgroundInteraction = presentationChrome.allowsBackgroundInteraction
        let scrimDismissesSheet =
            !allowsBackgroundInteraction
            && !presentationChrome.interactiveDismissDisabled
        let scrimNode = Controls.panel(
            backgroundColor: Color(red: 0.029, green: 0.029, blue: 0.029, alpha: 0.48),
            isHitTestVisible: scrimDismissesSheet
        )
        if allowsBackgroundInteraction {
            scrimNode.nodeTag = "sheet-scrim-background-interactive"
        } else if presentationChrome.interactiveDismissDisabled {
            scrimNode.nodeTag = "sheet-scrim-dismiss-disabled"
        } else {
            scrimNode.nodeTag = "sheet-scrim-dismiss-enabled"
        }
        let palette = context.controlPalette
        let sheetBackgroundColor =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundColor
            : palette.elevatedSurface
        let sheetBackgroundGradient =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundGradient
            : nil
        let sheetCornerRadius =
            presentationChrome.hasCornerRadiusOverride
            ? normalizedPresentationCornerRadius(presentationChrome.cornerRadius, defaultValue: 14)
            : 14
        let sheetNode = Controls.stackPanel(
            backgroundColor: sheetBackgroundColor,
            backgroundGradient: sheetBackgroundGradient,
            borderColor: palette.elevatedSurfaceBorder,
            borderWidth: 1,
            cornerRadius: sheetCornerRadius,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 10,
                padding: EdgeInsets(top: 18, leading: 18, bottom: 18, trailing: 18),
                alignment: .stretch
            ),
            // Hit-test visible so clicks on the sheet's padding do not fall
            // through to the dismissal scrim behind it.
            isHitTestVisible: true,
            children: retainedPresentationChildren(
                contentNode: sheetContentNode,
                chrome: presentationChrome,
                palette: palette,
                wrapsScrollingContent: true
            )
        )
        // Deferred painting keeps the presented sheet above all base content
        // and gives its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [scrimNode, sheetNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "sheet-overlay"
        if presentationChrome.hasIsModalOverride
            ? presentationChrome.isModal : !presentationChrome.allowsBackgroundInteraction
        {
            overlayContainer.accessibilityTraits.insert(.isModal)
        }
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        let focusedAtPresentation = runtime.focusedNode
        let dismissSheet: @MainActor () -> Void
        if let hostedDismissal {
            hostedDismissal.materialize { [weak runtime] admission in
                guard let runtime, admission(), let currentRoot = retainedCurrentSheetRoot(root, in: runtime),
                    admission(), let currentBase = currentRoot.children.first,
                    let currentOverlay = currentRoot.children.first(where: { $0.nodeTag == "sheet-overlay" })
                else { return nil }
                let wasModal = currentOverlay.accessibilityTraits.contains(.isModal)
                retainedRestorePresentationFocus(
                    runtime: runtime, focusedAtPresentation: focusedAtPresentation,
                    baseNode: currentBase, overlayNode: currentOverlay)
                return { [weak runtime, weak currentOverlay] in
                    guard wasModal, let runtime, let currentOverlay,
                        retainedPresentationNode(currentOverlay, isWithin: runtime.root)
                    else { return }
                    currentOverlay.accessibilityTraits.insert(.isModal)
                }
            }
            dismissSheet = { hostedDismissal.dismissInteractively() }
        } else {
            dismissSheet = {
                retainedRestorePresentationFocus(
                    runtime: runtime,
                    focusedAtPresentation: focusedAtPresentation,
                    baseNode: baseNode,
                    overlayNode: overlayContainer
                )
                onInteractiveDismiss()
            }
        }
        if scrimDismissesSheet {
            scrimNode.onActivate = {
                dismissSheet()
            }
        }
        attachRetainedEscapeDismiss(to: root, within: overlayContainer, dismiss: dismissSheet)

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            // The scrim always covers the full canvas, no matter where the
            // presentation's root sits in the window.
            let scrimFrame = retainedPresentationCanvasScrimFrame(root: root, canvasSize: context.canvasSize)
            if scrimNode.frame != scrimFrame {
                scrimNode.frame = scrimFrame
            }

            var sheetSize = sheetNode.intrinsicContentSize()
            if let detentHeight = retainedPresentationHeight(
                chrome: presentationChrome,
                boundsSize: bounds.size
            ) {
                sheetSize.height = detentHeight
            }
            let sheetOrigin = Alignment.bottom.frameOrigin(
                for: sheetSize,
                in: bounds.size,
                layoutDirection: context.layoutDirection
            )
            let sheetFrame = Rect(origin: sheetOrigin, size: sheetSize)
            if sheetNode.frame != sheetFrame {
                sheetNode.frame = sheetFrame
            }
        }

        return root
    }
}
@MainActor
private func retainedFullScreenCoverPresentation(
    base: Component,
    cover: Component,
    context: ViewBuildContext
) -> Component {
    Component { runtime in
        let palette = context.controlPalette
        let baseNode = base.makeNode(runtime: runtime)
        let coverContentNode = cover.makeNode(runtime: runtime)
        let presentationChrome = retainedPresentationChrome(in: coverContentNode)
        let coverBackgroundColor =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundColor
            : palette.windowBackground
        let coverBackgroundGradient =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundGradient
            : nil
        let coverNode = Controls.stackPanel(
            backgroundColor: coverBackgroundColor,
            backgroundGradient: coverBackgroundGradient,
            cornerRadius: presentationChrome.hasCornerRadiusOverride
                ? normalizedPresentationCornerRadius(presentationChrome.cornerRadius, defaultValue: 0)
                : 0,
            clipsToBounds: presentationChrome.hasCornerRadiusOverride,
            stackLayout: .vertical(
                spacing: 0,
                padding: EdgeInsets(top: 24, leading: 24, bottom: 24, trailing: 24),
                alignment: .stretch,
                mainAlignment: .start
            ),
            // Hit-test visible so the modal cover swallows clicks instead of
            // letting them fall through to the base content it covers.
            isHitTestVisible: true,
            children: retainedPresentationChildren(
                contentNode: coverContentNode, chrome: presentationChrome, palette: palette)
        )
        // Deferred painting keeps the cover above all base content and gives
        // its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [coverNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "full-screen-cover-overlay"
        if !presentationChrome.hasIsModalOverride || presentationChrome.isModal {
            overlayContainer.accessibilityTraits.insert(.isModal)
        }
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            if coverNode.frame != boundsFrame {
                coverNode.frame = boundsFrame
            }
        }

        return root
    }
}
@MainActor
private func retainedPopoverPresentation(
    base: Component,
    popover: Component,
    context: ViewBuildContext,
    attachmentAnchor: PopoverAttachmentAnchor,
    arrowEdge: Edge,
    onInteractiveDismiss: @escaping @MainActor () -> Void
) -> Component {
    Component { runtime in
        let baseNode = base.makeNode(runtime: runtime)
        let popoverContentNode = popover.makeNode(runtime: runtime)
        let presentationChrome = retainedPresentationChrome(in: popoverContentNode)
        let palette = context.controlPalette
        let popoverBackgroundColor =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundColor
            : palette.elevatedSurface
        let popoverBackgroundGradient =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundGradient
            : nil
        let popoverCornerRadius =
            presentationChrome.hasCornerRadiusOverride
            ? normalizedPresentationCornerRadius(presentationChrome.cornerRadius, defaultValue: 12)
            : 12
        let popoverNode = Controls.stackPanel(
            backgroundColor: popoverBackgroundColor,
            backgroundGradient: popoverBackgroundGradient,
            borderColor: palette.elevatedSurfaceBorder,
            borderWidth: 1,
            shadowColor: Color(red: 0.0, green: 0.0, blue: 0.0, alpha: 0.28),
            shadowOffset: Point(x: 0, y: 10),
            shadowSpread: 16,
            cornerRadius: popoverCornerRadius,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 8,
                padding: EdgeInsets(top: 14, leading: 14, bottom: 14, trailing: 14),
                alignment: .stretch
            ),
            // Hit-test visible so clicks on the popover's padding do not fall
            // through to the dismissal scrim behind it.
            isHitTestVisible: true,
            children: retainedPresentationChildren(
                contentNode: popoverContentNode, chrome: presentationChrome, palette: palette)
        )
        // Full-canvas transparent scrim: sits behind the popover inside the
        // deferred overlay and dismisses on outside pointer-down.
        let scrimNode = Controls.panel(isHitTestVisible: true)
        scrimNode.nodeTag = "popover-dismiss-scrim"
        // Deferred painting keeps the popover above all base content and gives
        // its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [scrimNode, popoverNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "popover-overlay"
        if presentationChrome.hasIsModalOverride
            ? presentationChrome.isModal : !presentationChrome.allowsBackgroundInteraction
        {
            overlayContainer.accessibilityTraits.insert(.isModal)
        }
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        let focusedAtPresentation = runtime.focusedNode
        let dismissPopover: @MainActor () -> Void = {
            retainedRestorePresentationFocus(
                runtime: runtime,
                focusedAtPresentation: focusedAtPresentation,
                baseNode: baseNode,
                overlayNode: overlayContainer
            )
            onInteractiveDismiss()
        }
        scrimNode.onPointerDown = {
            dismissPopover()
        }
        attachRetainedEscapeDismiss(to: root, within: overlayContainer, dismiss: dismissPopover)

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            // The scrim always covers the full canvas, no matter where the
            // presentation's root sits in the window.
            let scrimFrame = retainedPresentationCanvasScrimFrame(root: root, canvasSize: context.canvasSize)
            if scrimNode.frame != scrimFrame {
                scrimNode.frame = scrimFrame
            }

            let popoverSize = popoverNode.intrinsicContentSize()
            let popoverOrigin = popoverOrigin(
                for: popoverSize,
                in: bounds.size,
                attachmentAnchor: attachmentAnchor,
                arrowEdge: arrowEdge,
                layoutDirection: context.layoutDirection
            )
            let popoverFrame = Rect(origin: popoverOrigin, size: popoverSize)
            if popoverNode.frame != popoverFrame {
                popoverNode.frame = popoverFrame
            }
        }

        return root
    }
}
@MainActor
private func retainedInspectorPresentation(
    base: Component,
    inspector: Component,
    context: ViewBuildContext,
    onInteractiveDismiss: @escaping @MainActor () -> Void
) -> Component {
    Component { runtime in
        let baseNode = base.makeNode(runtime: runtime)
        let inspectorContentNode = inspector.makeNode(runtime: runtime)
        let presentationChrome = retainedPresentationChrome(in: inspectorContentNode)
        let palette = context.controlPalette
        let inspectorBackgroundColor =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundColor
            : palette.elevatedSurface
        let inspectorBackgroundGradient =
            presentationChrome.hasBackgroundOverride
            ? presentationChrome.backgroundGradient
            : nil
        let style = baseNode.inspectorPresentationStyle ?? .automatic
        let isSheet = style.kind == .sheet

        let inspectorNode = Controls.stackPanel(
            backgroundColor: inspectorBackgroundColor,
            backgroundGradient: inspectorBackgroundGradient,
            borderColor: isSheet ? .clear : palette.elevatedSurfaceBorder,
            borderWidth: isSheet ? 0 : 1,
            cornerRadius: isSheet ? 12 : 0,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 10,
                padding: EdgeInsets(top: 18, leading: 18, bottom: 18, trailing: 18),
                alignment: .stretch
            ),
            isHitTestVisible: false,
            children: retainedPresentationChildren(
                contentNode: inspectorContentNode,
                chrome: presentationChrome,
                palette: palette,
                wrapsScrollingContent: true
            )
        )
        // Deferred painting keeps the inspector above all base content and
        // gives its subtree hit-test priority over base content. An inspector
        // is non-modal, so there is no scrim: base content stays interactive.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [inspectorNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "inspector-overlay"
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        let focusedAtPresentation = runtime.focusedNode
        let dismissInspector: @MainActor () -> Void = {
            retainedRestorePresentationFocus(
                runtime: runtime,
                focusedAtPresentation: focusedAtPresentation,
                baseNode: baseNode,
                overlayNode: overlayContainer
            )
            onInteractiveDismiss()
        }
        attachRetainedEscapeDismiss(to: root, dismiss: dismissInspector)

        let columnWidth = baseNode.inspectorColumnWidth

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }

            let inspectorWidth: Double = columnWidth ?? 320
            let inspectorSize = inspectorNode.intrinsicContentSize()
            let finalInspectorWidth = min(inspectorWidth, bounds.size.width)

            let inspectorFrame: Rect
            if isSheet {
                let sheetWidth = min(finalInspectorWidth, bounds.size.width * 0.9)
                let sheetHeight = min(inspectorSize.height, bounds.size.height * 0.8)
                inspectorFrame = Rect(
                    origin: Point(
                        x: (bounds.size.width - sheetWidth) / 2,
                        y: (bounds.size.height - sheetHeight) / 2
                    ),
                    size: Size(width: sheetWidth, height: sheetHeight)
                )
            } else {
                inspectorFrame = Rect(
                    origin: Point(x: bounds.size.width - finalInspectorWidth, y: 0),
                    size: Size(width: finalInspectorWidth, height: bounds.size.height)
                )
            }
            if inspectorNode.frame != inspectorFrame {
                inspectorNode.frame = inspectorFrame
            }
        }

        return root
    }
}
private func popoverAttachmentPoint(_ anchor: PopoverAttachmentAnchor, in size: Size) -> Point {
    let unitPoint: UnitPoint
    switch anchor.kind {
    case .rect(let point), .point(let point):
        unitPoint = point
    }
    return Point(
        x: size.width * min(1, max(0, unitPoint.x)),
        y: size.height * min(1, max(0, unitPoint.y))
    )
}
private func resolvedPopoverArrowEdge(_ edge: Edge, layoutDirection: LayoutDirection) -> Edge {
    switch (edge, layoutDirection) {
    case (.leading, .rightToLeft):
        return .trailing
    case (.trailing, .rightToLeft):
        return .leading
    default:
        return edge
    }
}
private func clampedPopoverOrigin(_ origin: Point, popoverSize: Size, boundsSize: Size) -> Point {
    Point(
        x: min(max(0, boundsSize.width - popoverSize.width), max(0, origin.x)),
        y: min(max(0, boundsSize.height - popoverSize.height), max(0, origin.y))
    )
}
private func popoverOrigin(
    for popoverSize: Size,
    in boundsSize: Size,
    attachmentAnchor: PopoverAttachmentAnchor,
    arrowEdge: Edge,
    layoutDirection: LayoutDirection
) -> Point {
    let attachmentPoint = popoverAttachmentPoint(attachmentAnchor, in: boundsSize)
    let origin: Point
    switch resolvedPopoverArrowEdge(arrowEdge, layoutDirection: layoutDirection) {
    case .top:
        origin = Point(
            x: attachmentPoint.x - popoverSize.width * 0.5,
            y: attachmentPoint.y
        )
    case .bottom:
        origin = Point(
            x: attachmentPoint.x - popoverSize.width * 0.5,
            y: attachmentPoint.y - popoverSize.height
        )
    case .leading:
        origin = Point(
            x: attachmentPoint.x,
            y: attachmentPoint.y - popoverSize.height * 0.5
        )
    case .trailing:
        origin = Point(
            x: attachmentPoint.x - popoverSize.width,
            y: attachmentPoint.y - popoverSize.height * 0.5
        )
    }
    return clampedPopoverOrigin(origin, popoverSize: popoverSize, boundsSize: boundsSize)
}
@MainActor
private func retainedCompactPopoverAdaptation(
    chrome: RetainedPresentationChrome,
    context: ViewBuildContext
) -> RetainedPresentationAdaptation {
    guard chrome.hasCompactAdaptationOverride else {
        return .popover
    }

    var adaptation: RetainedPresentationAdaptation?
    let environment = context.environmentValues
    if environment.horizontalSizeClass == .compact {
        adaptation = chrome.horizontalCompactAdaptation
    }
    if environment.verticalSizeClass == .compact {
        adaptation = chrome.verticalCompactAdaptation
    }
    return adaptation ?? .popover
}
@MainActor
private func retainedCompactAdaptivePopoverPresentation(
    base: Component,
    popover: Component,
    context: ViewBuildContext,
    attachmentAnchor: PopoverAttachmentAnchor,
    arrowEdge: Edge,
    onInteractiveDismiss: @escaping @MainActor @Sendable () -> Void
) -> Component {
    Component { runtime in
        let baseNode = base.makeNode(runtime: runtime)
        let popoverContentNode = popover.makeNode(runtime: runtime)
        let presentationChrome = retainedPresentationChrome(in: popoverContentNode)
        let baseComponent = Component { _ in baseNode }
        let popoverComponent = Component { _ in popoverContentNode }

        switch retainedCompactPopoverAdaptation(chrome: presentationChrome, context: context) {
        case .sheet:
            return retainedSheetPresentation(
                base: baseComponent,
                sheet: popoverComponent,
                context: context,
                onInteractiveDismiss: onInteractiveDismiss
            )
            .makeNode(runtime: runtime)
        case .fullScreenCover:
            return retainedFullScreenCoverPresentation(
                base: baseComponent,
                cover: popoverComponent,
                context: context
            )
            .makeNode(runtime: runtime)
        case .automatic, .none, .popover:
            return retainedPopoverPresentation(
                base: baseComponent,
                popover: popoverComponent,
                context: context,
                attachmentAnchor: attachmentAnchor,
                arrowEdge: arrowEdge,
                onInteractiveDismiss: onInteractiveDismiss
            )
            .makeNode(runtime: runtime)
        }
    }
}
@MainActor
private func retainedAlertModifier<Content: View>(
    content: Content, transform: @escaping (AnyView, ViewBuildContext) -> Component
) -> ModifiedView<Content> {
    ModifiedView(content: content) { value, context in
        if context.stateMountCoordinator != nil { return transform(value, context) }
        // Raw Components are reusable across builds and runtimes. Their
        // materialization owns a fresh declaration, not the reusable factory.
        return Component { runtime in transform(value, context).makeNode(runtime: runtime) }
    }
}

@MainActor
private func retainedAlertDeclaration(
    context: ViewBuildContext, configuration: RetainedAlertConfiguration?
) -> RetainedAlertDeclaration {
    if let coordinator = context.stateMountCoordinator {
        return coordinator.alertDeclaration(
            at: context.retainedViewIdentity, configuration: configuration,
            lazyAttribution: context.viewIdentity.lazyList,
            descriptorAttribution: context.viewIdentity.descriptorComponent)
    }
    return .raw(configuration: configuration)
}

@MainActor
private func retainedBooleanAlertDeclaration(
    isPresented: Binding<Bool>, context: ViewBuildContext, payload: Any? = nil
) -> RetainedAlertDeclaration {
    retainedAlertDeclaration(
        context: context,
        configuration: RetainedAlertConfiguration(
            payload: payload,
            validate: { admission in
                guard admission() else { return false }
                let presented = isPresented.wrappedValue
                return admission() && presented
            }, reset: { isPresented.wrappedValue = false }, invalidate: context.retainedAlertInvalidation))
}

private enum RetainedAlertHostIdentity {}

@MainActor
private func retainedUnpresentedAlert(base: Component, context: ViewBuildContext) -> Component {
    let declaration = retainedAlertDeclaration(context: context, configuration: nil)
    let identity = context.retainedViewIdentity.appending(.view(ObjectIdentifier(RetainedAlertHostIdentity.self)))
    return Component { runtime in
        let root = Controls.panel(
            layoutMode: .absolute, isHitTestVisible: false, children: [base.makeNode(runtime: runtime)])
        root.retainedViewIdentity = identity
        declaration.materialize(on: root, runtime: runtime)
        root.onLayout = { bounds in
            guard let base = declaration.layoutHost()?.children.first else { return }
            let frame = Rect(origin: .zero, size: bounds.size)
            if base.frame != frame { base.frame = frame }
        }
        return root
    }
}

@MainActor
private func attachRetainedAlertEscape(to node: ViewNode, declaration: RetainedAlertDeclaration) {
    declaration.installEscape(on: node)
    for child in node.children { attachRetainedAlertEscape(to: child, declaration: declaration) }
}

@MainActor
private func retainedAlertPresentation(
    base: Component,
    title: Component,
    message: Component?,
    actions: Component,
    context: ViewBuildContext,
    declaration: RetainedAlertDeclaration
) -> Component {
    let identity = context.retainedViewIdentity.appending(.view(ObjectIdentifier(RetainedAlertHostIdentity.self)))
    return Component { runtime in
        let palette = context.controlPalette
        let baseNode = base.makeNode(runtime: runtime)
        // Modal scrim: swallows outside clicks so they cannot reach the base
        // content, but does not dismiss (matching SwiftUI alert behavior).
        let scrimNode = Controls.panel(
            backgroundColor: Color(red: 0.029, green: 0.029, blue: 0.029, alpha: 0.52),
            isHitTestVisible: true
        )
        scrimNode.nodeTag = "alert-scrim"

        var alertChildren = [title.makeNode(runtime: runtime)]
        if let message {
            alertChildren.append(message.makeNode(runtime: runtime))
        }
        alertChildren.append(actions.makeNode(runtime: runtime))

        let alertNode = Controls.stackPanel(
            preferredSize: Size(width: 300, height: 0),
            backgroundColor: palette.elevatedSurface,
            borderColor: palette.elevatedSurfaceBorder,
            borderWidth: 1,
            shadowColor: Elevation.e3.color(for: palette.colorScheme),
            shadowOffset: Point(x: 0, y: Elevation.e3.offsetY(for: palette.colorScheme)),
            shadowSpread: Elevation.e3.radius(for: palette.colorScheme),
            cornerRadius: MacOSControlMetrics.Radius.xl,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 12,
                padding: EdgeInsets(top: 18, leading: 18, bottom: 18, trailing: 18),
                alignment: .stretch
            ),
            // Hit-test visible so clicks on the alert's padding do not fall
            // through to the scrim behind it.
            isHitTestVisible: true,
            children: alertChildren
        )
        // Deferred painting keeps the alert above all base content and gives
        // its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [scrimNode, alertNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "alert-overlay"
        overlayContainer.accessibilityTraits.insert(.isModal)
        let root = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        root.retainedViewIdentity = identity
        declaration.materialize(on: root, runtime: runtime)
        attachRetainedAlertEscape(to: root, declaration: declaration)
        let canvasSize = context.canvasSize
        let layoutDirection = context.layoutDirection
        root.onLayout = { bounds in
            guard let root = declaration.layoutHost(), let baseNode = root.children.first,
                let overlayContainer = root.children.dropFirst().first,
                let scrimNode = overlayContainer.children.first,
                let alertNode = overlayContainer.children.dropFirst().first
            else { return }
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            // The scrim always covers the full canvas, no matter where the
            // presentation's root sits in the window.
            let scrimFrame = retainedPresentationCanvasScrimFrame(root: root, canvasSize: canvasSize)
            if scrimNode.frame != scrimFrame {
                scrimNode.frame = scrimFrame
            }

            let alertSize = alertNode.intrinsicContentSize()
            let alertOrigin = Alignment.center.frameOrigin(
                for: alertSize,
                in: bounds.size,
                layoutDirection: layoutDirection
            )
            let alertFrame = Rect(origin: alertOrigin, size: alertSize)
            if alertNode.frame != alertFrame {
                alertNode.frame = alertFrame
            }
        }

        return root
    }
}
@MainActor
private func retainedAlertPresentation(
    base: Component,
    alert: Alert,
    context: ViewBuildContext,
    declaration: RetainedAlertDeclaration
) -> Component {
    let alertContext =
        declaration.presentationContext(context)
        .withEnvironmentValue(\.dismiss, DismissAction(handler: { declaration.dismiss() }))
        .withEnvironmentValue(\.isPresented, true)
    let title = alert.title
        .font(.headline)
        .multilineTextAlignment(.center)
        .makeComponent(context: alertContext)
    let message = alert.message?
        .font(.body)
        .foregroundStyle(.secondary)
        .multilineTextAlignment(.center)
        .makeComponent(context: alertContext)
    let actions = retainedAlertActionsComponent(
        buttons: alert.buttons,
        context: alertContext.withEnvironmentValue(
            \.retainedAlertActionScope, RetainedAlertActionScope(declaration: declaration, context: alertContext))
    )

    return retainedAlertPresentation(
        base: base,
        title: title,
        message: message,
        actions: actions,
        context: context,
        declaration: declaration
    )
}
@MainActor
private func retainedAlertActionsComponent(
    buttons: [Alert.Button],
    context: ViewBuildContext
) -> Component {
    let actionButtons = (buttons.isEmpty ? [.default(Text("OK"))] : buttons).map { button in
        AnyView(
            Button(button.label.plainContent, role: button.role) {
                button.action?()
            }
            .buttonStyle(.borderedProminent)
        )
    }

    return composeComponent(
        from: actionButtons,
        context: context,
        fallbackLayout: .stack(.horizontal(spacing: 8, alignment: .stretch, mainAlignment: .end))
    )
}
@MainActor
private func retainedAlertBuilderPresentation(
    base: Component,
    title: Text,
    messageViews: [AnyView],
    actionViews: [AnyView],
    context: ViewBuildContext,
    declaration: RetainedAlertDeclaration
) -> Component {
    let alertContext =
        declaration.presentationContext(context)
        .withEnvironmentValue(\.dismiss, DismissAction(handler: { declaration.dismiss() }))
        .withEnvironmentValue(\.isPresented, true)
    let titleComponent =
        title
        .font(.headline)
        .multilineTextAlignment(.center)
        .makeComponent(context: alertContext)
    let messageComponent =
        messageViews.isEmpty
        ? nil
        : composeComponent(
            from: messageViews,
            context: alertContext.withEnvironmentValue(\.foregroundStyle, .color(.secondary)),
            fallbackLayout: .stack(.vertical(spacing: 4, alignment: .center))
        )
    let actions =
        actionViews.isEmpty
        ? [AnyView(Button("OK") {}.buttonStyle(.borderedProminent))]
        : actionViews
    let actionsComponent = composeComponent(
        from: actions,
        context: alertContext.withEnvironmentValue(
            \.retainedAlertActionScope, RetainedAlertActionScope(declaration: declaration, context: alertContext)),
        fallbackLayout: .stack(.horizontal(spacing: 8, alignment: .stretch, mainAlignment: .end))
    )

    return retainedAlertPresentation(
        base: base,
        title: titleComponent,
        message: messageComponent,
        actions: actionsComponent,
        context: context,
        declaration: declaration
    )
}
@MainActor
private func retainedConfirmationDialogPresentation(
    base: Component,
    title: Text,
    titleVisibility: Visibility,
    messageViews: [AnyView],
    actionViews: [AnyView],
    context: ViewBuildContext,
    dismiss: @escaping @MainActor () -> Void
) -> Component {
    let dialogContext =
        context
        .withEnvironmentValue(\.dismiss, DismissAction(handler: dismiss))
        .withEnvironmentValue(\.isPresented, true)
    var dialogChildren: [Component] = []
    if titleVisibility != .hidden {
        dialogChildren.append(
            title
                .font(.headline)
                .multilineTextAlignment(.center)
                .makeComponent(context: dialogContext)
        )
    }
    if !messageViews.isEmpty {
        dialogChildren.append(
            composeComponent(
                from: messageViews,
                context: dialogContext.withEnvironmentValue(\.foregroundStyle, .color(.secondary)),
                fallbackLayout: .stack(.vertical(spacing: 4, alignment: .center))
            )
        )
    }

    let actions =
        actionViews.isEmpty
        ? [AnyView(Button("Cancel", role: .cancel) { dismiss() }.buttonStyle(.borderedProminent))]
        : actionViews
    dialogChildren.append(
        composeComponent(
            from: actions,
            context: dialogContext,
            fallbackLayout: .stack(.vertical(spacing: 8, alignment: .stretch))
        )
    )

    return Component { runtime in
        let palette = context.controlPalette
        let baseNode = base.makeNode(runtime: runtime)
        // Full-canvas scrim: swallows outside clicks and dismisses on outside
        // pointer-down, matching SwiftUI confirmationDialog behavior.
        let scrimNode = Controls.panel(
            backgroundColor: Color(red: 0.029, green: 0.029, blue: 0.029, alpha: 0.44),
            isHitTestVisible: true
        )
        scrimNode.nodeTag = "confirmation-dialog-scrim"
        let dialogNode = Controls.stackPanel(
            preferredSize: Size(width: 340, height: 0),
            backgroundColor: palette.elevatedSurface,
            borderColor: palette.elevatedSurfaceBorder,
            borderWidth: 1,
            shadowColor: Elevation.e3.color(for: palette.colorScheme),
            shadowOffset: Point(x: 0, y: Elevation.e3.offsetY(for: palette.colorScheme)),
            shadowSpread: Elevation.e3.radius(for: palette.colorScheme),
            cornerRadius: MacOSControlMetrics.Radius.xl,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 12,
                padding: EdgeInsets(top: 18, leading: 18, bottom: 18, trailing: 18),
                alignment: .stretch
            ),
            // Hit-test visible so clicks on the dialog's padding do not fall
            // through to the dismissal scrim behind it.
            isHitTestVisible: true,
            children: dialogChildren.map { $0.makeNode(runtime: runtime) }
        )
        // Deferred painting keeps the dialog above all base content and gives
        // its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [scrimNode, dialogNode]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "confirmation-dialog-overlay"
        overlayContainer.accessibilityTraits.insert(.isModal)
        let root = Controls.panel(
            preferredSize: baseNode.intrinsicContentSize(),
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        let focusedAtPresentation = runtime.focusedNode
        let restoreFocus: @MainActor () -> Void = {
            retainedRestorePresentationFocus(
                runtime: runtime,
                focusedAtPresentation: focusedAtPresentation,
                baseNode: baseNode,
                overlayNode: overlayContainer
            )
        }
        let dismissDialog: @MainActor () -> Void = {
            restoreFocus()
            dismiss()
        }
        scrimNode.onPointerDown = {
            dismissDialog()
        }
        attachRetainedEscapeDismiss(to: root, within: overlayContainer, dismiss: dismissDialog)
        attachRetainedPresentationFocusRestore(to: dialogNode, restoreFocus: restoreFocus)

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            // The scrim always covers the full canvas, no matter where the
            // presentation's root sits in the window.
            let scrimFrame = retainedPresentationCanvasScrimFrame(root: root, canvasSize: context.canvasSize)
            if scrimNode.frame != scrimFrame {
                scrimNode.frame = scrimFrame
            }

            let dialogSize = dialogNode.intrinsicContentSize()
            let dialogOrigin = Alignment.bottom.frameOrigin(
                for: dialogSize,
                in: bounds.size,
                layoutDirection: context.layoutDirection
            )
            let dialogFrame = Rect(origin: dialogOrigin, size: dialogSize)
            if dialogNode.frame != dialogFrame {
                dialogNode.frame = dialogFrame
            }
        }

        return root
    }
}
@MainActor
private func retainedActionSheetPresentation(
    base: Component,
    actionSheet: ActionSheet,
    context: ViewBuildContext,
    dismiss: @escaping @MainActor () -> Void
) -> Component {
    let sheetContext =
        context
        .withEnvironmentValue(\.dismiss, DismissAction(handler: dismiss))
        .withEnvironmentValue(\.isPresented, true)
    let messageViews = actionSheet.message.map { [AnyView($0.foregroundStyle(.secondary))] } ?? []
    let buttons = (actionSheet.buttons.isEmpty ? [.cancel()] : actionSheet.buttons).map { button in
        AnyView(
            Button(button.label.plainContent, role: button.role) {
                button.action?()
                dismiss()
            }
            .buttonStyle(.borderedProminent)
        )
    }

    return retainedConfirmationDialogPresentation(
        base: base,
        title: actionSheet.title,
        titleVisibility: .visible,
        messageViews: messageViews,
        actionViews: buttons,
        context: sheetContext,
        dismiss: dismiss
    )
}
@MainActor
private final class RetainedContextMenuState {
    var isPresented = false
    var anchor = Point.zero
}
@MainActor
private func installRetainedContextMenuHandler(
    on node: ViewNode,
    state: RetainedContextMenuState,
    context: ViewBuildContext
) {
    let previousHandler = node.onContextMenu
    node.isHitTestVisible = true
    node.onContextMenu = { point in
        previousHandler?(point)
        state.anchor = point
        state.isPresented = true
        context.invalidate()
    }
}
@MainActor
private func attachRetainedActivationDismiss(to node: ViewNode, dismiss: @escaping @MainActor () -> Void) {
    if let activate = node.onActivate {
        node.onActivate = {
            activate()
            dismiss()
        }
    }

    for child in node.children {
        attachRetainedActivationDismiss(to: child, dismiss: dismiss)
    }
}
@MainActor
private func retainedContextMenuPresentation(
    base: Component,
    menuItems: [AnyView],
    preview: [AnyView],
    state: RetainedContextMenuState,
    context: ViewBuildContext
) -> Component {
    let dismiss: @MainActor () -> Void = {
        guard state.isPresented else {
            return
        }

        state.isPresented = false
        context.invalidate()
    }
    let menuContext =
        context
        .withButtonStyle(.plain)
        .withControlSize(.small)
        .withEnvironmentValue(\.dismiss, DismissAction(handler: dismiss))
        .withEnvironmentValue(\.isPresented, true)
    let previewComponent =
        preview.isEmpty
        ? nil
        : composeComponent(
            from: preview,
            context: menuContext.withViewIdentityRole(.presentation),
            fallbackLayout: .stack(.vertical(spacing: 4, alignment: .stretch)),
            isHitTestVisible: false
        )
    let itemComponent = composeComponent(
        from: menuItems,
        context: menuContext.withViewIdentityRole(.menu),
        fallbackLayout: .stack(.vertical(spacing: 2, alignment: .stretch)),
        isHitTestVisible: false
    )

    return Component { runtime in
        let palette = context.controlPalette
        let baseNode = base.makeNode(runtime: runtime)
        installRetainedContextMenuHandler(on: baseNode, state: state, context: context)
        guard state.isPresented else {
            return baseNode
        }

        var panelChildren: [ViewNode] = []
        if let previewComponent {
            panelChildren.append(previewComponent.makeNode(runtime: runtime))
        }
        let itemNode = itemComponent.makeNode(runtime: runtime)
        panelChildren.append(itemNode)

        let menuPanel = Controls.stackPanel(
            preferredSize: Size(width: 220, height: 0),
            backgroundColor: palette.elevatedSurface,
            borderColor: palette.elevatedSurfaceBorder,
            borderWidth: 1,
            shadowColor: Color(red: 0.0, green: 0.0, blue: 0.0, alpha: 0.28),
            shadowOffset: Point(x: 0, y: 10),
            shadowSpread: 12,
            cornerRadius: 10,
            clipsToBounds: true,
            stackLayout: .vertical(
                spacing: 6,
                padding: EdgeInsets(top: 6, leading: 6, bottom: 6, trailing: 6),
                alignment: .stretch
            ),
            // Hit-test visible so clicks on the panel's padding do not fall
            // through to the dismissal scrim behind it.
            isHitTestVisible: true,
            children: panelChildren
        )
        // Full-canvas transparent scrim: sits behind the panel inside the
        // deferred overlay and dismisses on outside pointer-down.
        let scrimNode = Controls.panel(isHitTestVisible: true)
        scrimNode.nodeTag = "context-menu-dismiss-scrim"
        // Deferred painting keeps the open context menu above all base content
        // and gives its subtree hit-test priority over base content.
        let overlayContainer = Controls.panel(
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [scrimNode, menuPanel]
        )
        overlayContainer.paintsInDeferredPhase = true
        overlayContainer.nodeTag = "context-menu-overlay"
        overlayContainer.accessibilityTraits.insert(.isModal)
        let root = Controls.panel(
            preferredSize: baseNode.intrinsicContentSize(),
            layoutMode: .absolute,
            isHitTestVisible: false,
            children: [baseNode, overlayContainer]
        )

        let focusedAtPresentation = runtime.focusedNode
        let dismissWithFocusRestore: @MainActor () -> Void = {
            retainedRestorePresentationFocus(
                runtime: runtime,
                focusedAtPresentation: focusedAtPresentation,
                baseNode: baseNode,
                overlayNode: overlayContainer
            )
            dismiss()
        }
        scrimNode.onPointerDown = {
            dismissWithFocusRestore()
        }
        attachRetainedActivationDismiss(to: itemNode, dismiss: dismissWithFocusRestore)
        attachRetainedEscapeDismiss(to: root, within: overlayContainer, dismiss: dismissWithFocusRestore)

        root.onLayout = { bounds in
            let boundsFrame = Rect(origin: .zero, size: bounds.size)
            if baseNode.frame != boundsFrame {
                baseNode.frame = boundsFrame
            }
            if overlayContainer.frame != boundsFrame {
                overlayContainer.frame = boundsFrame
            }
            // The scrim always covers the full canvas, no matter where the
            // presentation's root sits in the window.
            let scrimFrame = retainedPresentationCanvasScrimFrame(root: root, canvasSize: context.canvasSize)
            if scrimNode.frame != scrimFrame {
                scrimNode.frame = scrimFrame
            }

            let panelSize = menuPanel.intrinsicContentSize()
            let maxX = max(0, bounds.size.width - panelSize.width)
            let maxY = max(0, bounds.size.height - panelSize.height)
            let origin = Point(
                x: min(max(0, state.anchor.x), maxX),
                y: min(max(0, state.anchor.y), maxY)
            )
            let panelFrame = Rect(origin: origin, size: panelSize)
            if menuPanel.frame != panelFrame {
                menuPanel.frame = panelFrame
            }
        }

        return root
    }
}
extension View {
    public func modifier<Modifier: ViewModifier>(_ modifier: Modifier) -> ModifiedContent<Self, Modifier> {
        ModifiedContent(content: self, modifier: modifier)
    }

    public func equatable() -> EquatableView<Self> where Self: Equatable {
        EquatableView(content: self)
    }

    public func frame(width: Double? = nil, height: Double? = nil, alignment: Alignment = .center) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                // The frame owns its dimensions and aligns the child's measured
                // content inside them. Overwriting the child would stretch text
                // and replace the dimensions of an earlier frame modifier.
                // Intrinsic controls can separately opt into an explicit
                // proposal, without greedily filling every ordinary container.
                let acceptedAxes = childNode.explicitFrameFillAxes
                let fillAxes = LayoutFillAxes(
                    horizontal: childNode.layoutFillAxes.horizontal
                        || (width != nil && acceptedAxes.horizontal && childNode.fixedSizeAxes?.horizontal != true),
                    vertical: childNode.layoutFillAxes.vertical
                        || (height != nil && acceptedAxes.vertical && childNode.fixedSizeAxes?.vertical != true))
                if childNode.layoutFillAxes != fillAxes { childNode.layoutFillAxes = fillAxes }
                let root = Controls.stackPanel(
                    preferredSize: Size(width: width ?? 0, height: height ?? 0),
                    stackLayout: .vertical(
                        padding: .zero,
                        alignment: alignment.horizontal.stackAlignment(layoutDirection: context.layoutDirection),
                        mainAlignment: alignment.vertical.mainAlignment
                    ),
                    isHitTestVisible: false,
                    children: [childNode]
                )
                root.fixedPreferredSizeAxes = LayoutFillAxes(
                    horizontal: (width ?? 0) > 0 && (width?.isFinite ?? false),
                    vertical: (height ?? 0) > 0 && (height?.isFinite ?? false))
                root.forwardsStackMainAxisProposal = true
                return root
            }
        }
    }

    public func frame(alignment: Alignment) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                return Controls.stackPanel(
                    preferredSize: nil,
                    stackLayout: .vertical(
                        padding: .zero,
                        alignment: alignment.horizontal.stackAlignment(layoutDirection: context.layoutDirection),
                        mainAlignment: alignment.vertical.mainAlignment
                    ),
                    isHitTestVisible: false,
                    children: [childNode]
                )
            }
        }
    }

    public func frame(_ rect: CGRect) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                childNode.frame = Rect(
                    origin: Point(x: rect.origin.x, y: rect.origin.y),
                    size: Size(width: rect.size.width, height: rect.size.height))
                return childNode
            }
        }
    }

    public func frame(
        idealWidth: Double? = nil,
        idealHeight: Double? = nil,
        alignment: Alignment = .center
    ) -> some View {
        frame(
            minWidth: nil,
            idealWidth: idealWidth,
            maxWidth: nil,
            minHeight: nil,
            idealHeight: idealHeight,
            maxHeight: nil,
            alignment: alignment
        )
    }

    public func frame(
        minWidth: Double? = nil,
        idealWidth: Double? = nil,
        maxWidth: Double? = nil,
        minHeight: Double? = nil,
        idealHeight: Double? = nil,
        maxHeight: Double? = nil,
        alignment: Alignment = .center
    ) -> some View {
        let resolvedMinWidth = normalizedFrameMinimum(minWidth)
        let resolvedMinHeight = normalizedFrameMinimum(minHeight)
        let constraints = LayoutConstraints(
            minWidth: resolvedMinWidth,
            maxWidth: normalizedFrameMaximum(maxWidth, minimum: resolvedMinWidth),
            minHeight: resolvedMinHeight,
            maxHeight: normalizedFrameMaximum(maxHeight, minimum: resolvedMinHeight)
        )
        let idealSize = Size(
            width: normalizedFrameIdeal(idealWidth) ?? 0,
            height: normalizedFrameIdeal(idealHeight) ?? 0
        )
        let hasIdealSize = idealWidth != nil || idealHeight != nil
        // `.frame(maxWidth: .infinity)` is SwiftUI's "be greedy on this
        // axis": the view takes the whole proposal instead of its
        // intrinsic width. An infinite maximum is not a clamp, so the
        // runtime needs it as a fill axis, not as a constraint.
        let fillAxes = LayoutFillAxes(
            horizontal: maxWidth.map { !$0.isFinite } ?? false,
            vertical: maxHeight.map { !$0.isFinite } ?? false
        )

        return ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let root = Controls.stackPanel(
                    preferredSize: hasIdealSize ? idealSize : nil,
                    stackLayout: .vertical(
                        padding: .zero,
                        alignment: alignment.horizontal.stackAlignment(layoutDirection: context.layoutDirection),
                        mainAlignment: alignment.vertical.mainAlignment
                    ),
                    isHitTestVisible: false,
                    children: [childNode]
                )
                root.layoutConstraints = constraints
                root.layoutFillAxes = fillAxes
                return root
            }
        }
    }

    public func containerRelativeFrame(_ axes: Axis.Set, alignment: Alignment = .center) -> some View {
        containerRelativeFrame(axes, alignment: alignment) { length, _ in
            length
        }
    }

    public func containerRelativeFrame(
        _ axes: Axis.Set,
        count: Int,
        span: Int = 1,
        spacing: CGFloat,
        alignment: Alignment = .center
    ) -> some View {
        containerRelativeFrame(axes, alignment: alignment) { length, _ in
            containerRelativeSpanLength(
                availableLength: length,
                count: count,
                span: span,
                spacing: spacing
            )
        }
    }

    public func containerRelativeFrame(
        _ axes: Axis.Set,
        alignment: Alignment = .center,
        _ length: @escaping (CGFloat, Axis) -> CGFloat
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            let canvasSize = context.canvasSize
            let width =
                axes.contains(.horizontal)
                ? normalizedContainerRelativeLength(length(canvasSize.width, .horizontal))
                : nil
            let height =
                axes.contains(.vertical)
                ? normalizedContainerRelativeLength(length(canvasSize.height, .vertical))
                : nil

            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let root = Controls.stackPanel(
                    preferredSize: Size(width: width ?? 0, height: height ?? 0),
                    stackLayout: .vertical(
                        padding: .zero,
                        alignment: alignment.horizontal.stackAlignment(layoutDirection: context.layoutDirection),
                        mainAlignment: alignment.vertical.mainAlignment
                    ),
                    isHitTestVisible: false,
                    children: [childNode]
                )
                root.fixedPreferredSizeAxes = LayoutFillAxes(
                    horizontal: (width ?? 0) > 0 && (width?.isFinite ?? false),
                    vertical: (height ?? 0) > 0 && (height?.isFinite ?? false))
                root.forwardsStackMainAxisProposal = true
                return root
            }
        }
    }

    public func fixedSize() -> some View {
        fixedSize(horizontal: true, vertical: true)
    }

    public func fixedSize(horizontal: Bool, vertical: Bool) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                childNode.fixedSizeAxes = FixedSizeAxes(horizontal: horizontal, vertical: vertical)
                return childNode
            }
        }
    }

    public func ignoresSafeArea(_ regions: SafeAreaRegions = .all, edges: Edge.Set = .all) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let largeInset = Double.greatestFiniteMagnitude
                childNode.ignoresSafeAreaInsets = EdgeInsets(
                    top: edges.contains(.top) ? largeInset : 0,
                    leading: edges.contains(.leading) ? largeInset : 0,
                    bottom: edges.contains(.bottom) ? largeInset : 0,
                    trailing: edges.contains(.trailing) ? largeInset : 0
                )
                return childNode
            }
        }
    }

    public func edgesIgnoringSafeArea(_ edges: Edge.Set) -> some View {
        ignoresSafeArea(.all, edges: edges)
    }

    public func safeAreaPadding(_ length: Double? = nil) -> some View {
        padding(length)
    }

    public func safeAreaPadding(_ edges: Edge.Set, _ length: Double? = nil) -> some View {
        padding(edges, length)
    }

    public func safeAreaPadding(_ insets: EdgeInsets) -> some View {
        padding(insets)
    }

    public func safeAreaInset(
        edge: VerticalEdge,
        alignment: HorizontalAlignment = .center,
        spacing: Double? = nil,
        @ViewBuilder content insetContent: () -> [AnyView]
    ) -> some View {
        let insetViews = insetContent()
        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            let inset = composeComponent(
                from: insetViews,
                context: context.withViewIdentityRole(.safeAreaInset),
                fallbackLayout: .stack(
                    .vertical(
                        spacing: 0,
                        alignment: alignment.stackAlignment(layoutDirection: context.layoutDirection)
                    )),
                isHitTestVisible: false
            )

            return Component { runtime in
                let baseNode = base.makeNode(runtime: runtime)
                let insetNode = inset.makeNode(runtime: runtime)
                let children: [ViewNode]
                switch edge {
                case .top:
                    children = [insetNode, baseNode]
                case .bottom:
                    children = [baseNode, insetNode]
                }

                return Controls.stackPanel(
                    stackLayout: .vertical(
                        spacing: spacing ?? 0,
                        alignment: alignment.stackAlignment(layoutDirection: context.layoutDirection)
                    ),
                    isHitTestVisible: false,
                    children: children
                )
            }
        }
    }

    public func safeAreaInset(
        edge: HorizontalEdge,
        alignment: VerticalAlignment = .center,
        spacing: Double? = nil,
        @ViewBuilder content insetContent: () -> [AnyView]
    ) -> some View {
        let insetViews = insetContent()
        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            let inset = composeComponent(
                from: insetViews,
                context: context.withViewIdentityRole(.safeAreaInset),
                fallbackLayout: .stack(
                    .horizontal(
                        spacing: 0,
                        alignment: alignment.stackAlignment
                    )),
                isHitTestVisible: false
            )

            return Component { runtime in
                let baseNode = base.makeNode(runtime: runtime)
                let insetNode = inset.makeNode(runtime: runtime)
                let children: [ViewNode]
                switch edge.resolved(for: context.layoutDirection) {
                case .leading:
                    children = [insetNode, baseNode]
                case .trailing:
                    children = [baseNode, insetNode]
                }

                return Controls.stackPanel(
                    stackLayout: .horizontal(
                        spacing: spacing ?? 0,
                        alignment: alignment.stackAlignment
                    ),
                    isHitTestVisible: false,
                    children: children
                )
            }
        }
    }

