        _ title: S,
        isPresented: Binding<Bool>,
        titleVisibility: Visibility = .automatic,
        @ViewBuilder actions: @escaping () -> [AnyView],
        @ViewBuilder message: @escaping () -> [AnyView] = { [] }
    ) -> some View {
        confirmationDialog(
            LocalizedStringKey(String(title)),
            isPresented: isPresented,
            titleVisibility: titleVisibility,
            actions: actions,
            message: message
        )
    }

    public func confirmationDialog<Data>(
        _ titleKey: LocalizedStringKey,
        isPresented: Binding<Bool>,
        presenting data: Data?,
        titleVisibility: Visibility = .automatic,
        @ViewBuilder actions: @escaping (Data) -> [AnyView],
        @ViewBuilder message: @escaping (Data) -> [AnyView] = { _ in [] }
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            guard isPresented.wrappedValue, let presentedData = data else {
                return base
            }

            let dismiss: @MainActor () -> Void = {
                guard isPresented.wrappedValue else {
                    return
                }

                isPresented.wrappedValue = false
                context.invalidate()
            }

            return retainedConfirmationDialogPresentation(
                base: base,
                title: Text(titleKey),
                titleVisibility: titleVisibility,
                messageViews: message(presentedData),
                actionViews: actions(presentedData),
                context: context,
                dismiss: dismiss
            )
        }
    }

    public func confirmationDialog<S: StringProtocol, Data>(
        _ title: S,
        isPresented: Binding<Bool>,
        presenting data: Data?,
        titleVisibility: Visibility = .automatic,
        @ViewBuilder actions: @escaping (Data) -> [AnyView],
        @ViewBuilder message: @escaping (Data) -> [AnyView] = { _ in [] }
    ) -> some View {
        confirmationDialog(
            LocalizedStringKey(String(title)),
            isPresented: isPresented,
            presenting: data,
            titleVisibility: titleVisibility,
            actions: actions,
            message: message
        )
    }

    public func aspectRatio(_ aspectRatio: Double? = nil, contentMode: ContentMode) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            if case .fit = contentMode {
                return retainedAspectFitComponent(child: child, aspectRatio: aspectRatio)
            }
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let baseSize = childNode.intrinsicContentSize()
                let preferredSize = aspectRatioPreferredSize(
                    baseSize: baseSize,
                    requestedAspectRatio: aspectRatio,
                    contentMode: contentMode
                )
                return Controls.stackPanel(
                    preferredSize: preferredSize,
                    stackLayout: .vertical(padding: .zero, alignment: .center, mainAlignment: .center),
                    isHitTestVisible: false,
                    children: [childNode]
                )
            }
        }
    }

    public func scaledToFit() -> some View {
        aspectRatio(contentMode: .fit)
    }

    public func scaledToFill() -> some View {
        aspectRatio(contentMode: .fill)
    }

    public func padding(_ length: Double = 16) -> some View {
        padding(EdgeInsets.all(length))
    }

    public func padding(_ length: Double?) -> some View {
        padding(length ?? 16)
    }

    public func padding(_ edges: Edge.Set, _ length: Double = 16) -> some View {
        padding(
            EdgeInsets(
                top: edges.contains(.top) ? length : 0,
                leading: edges.contains(.leading) ? length : 0,
                bottom: edges.contains(.bottom) ? length : 0,
                trailing: edges.contains(.trailing) ? length : 0
            )
        )
    }

    public func padding(_ edges: Edge.Set, _ length: Double?) -> some View {
        padding(edges, length ?? 16)
    }

    public func padding(_ insets: EdgeInsets) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                return Controls.stackPanel(
                    // Centred, not `.start`. A padding wrapper holds exactly
                    // one child, so the two are identical whenever the
                    // wrapper is content-sized — and they differ in the one
                    // case that matters: `.padding(.horizontal, 12)
                    // .frame(height: 28)`, the shape of every chip, chassis
                    // and row in the app. A stated height stretches this
                    // wrapper, and with `.start` the label inside it went to
                    // the top of the box while the fill stayed 28 tall, so
                    // every button label, nav row and table header cell sat
                    // in the upper half of its own control. SwiftUI centres.
                    stackLayout: .vertical(padding: insets, alignment: .stretch, mainAlignment: .center),
                    isHitTestVisible: false,
                    children: [childNode]
                )
            }
        }
    }

