    public func background<Style: ShapeStyle, Clip: Shape>(
        _ style: Style,
        in shape: Clip,
        fillStyle: FillStyle = FillStyle()
    ) -> some View {
        let fill = resolvedStyleFill(from: style.retainedForegroundStyle)
        return shapedBackgroundStyle(color: fill.color, gradient: fill.gradient, shape: shape, fillStyle: fillStyle)
    }

    public func background<Clip: Shape>(
        in shape: Clip,
        fillStyle: FillStyle = FillStyle()
    ) -> some View {
        let clipStyle = (shape as? any RetainedClipShape)?.retainedClipShapeStyle ?? .rectangle
        let clipFillStyle = RetainedClipFillStyle(
            eoFill: fillStyle.isEOFilled,
            antialiased: fillStyle.isAntialiased
        )

        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            let fill = resolvedStyleFill(from: context.backgroundStyle)
            return Component { runtime in
                let baseNode = base.makeNode(runtime: runtime)
                let backgroundNode = Controls.panel(
                    backgroundColor: fill.color,
                    backgroundGradient: fill.gradient,
                    cornerRadius: clipStyle.staticCornerRadius,
                    clipsToBounds: true,
                    isHitTestVisible: false
                )
                backgroundNode.clipFillStyle = clipFillStyle
                let preferredSize = baseNode.intrinsicContentSize()
                let root = Controls.panel(
                    preferredSize: preferredSize,
                    layoutMode: .absolute,
                    isHitTestVisible: false,
                    children: [backgroundNode, baseNode]
                )

                root.onLayout = { bounds in
                    let frame = Rect(origin: .zero, size: bounds.size)
                    if baseNode.frame != frame {
                        baseNode.frame = frame
                    }
                    if backgroundNode.frame != frame {
                        backgroundNode.frame = frame
                    }
                    if case .capsule = clipStyle {
                        let radius = max(0, min(bounds.size.width, bounds.size.height) * 0.5)
                        if backgroundNode.cornerRadius != radius {
                            backgroundNode.cornerRadius = radius
                        }
                    }
                }

                return root
            }
        }
    }

    /// A background fill resolves against the appearance it lands in, exactly
    /// as the foreground path does.
    ///
    /// The semantic families are *sentinels*, not RGBA: the
    /// `NSColor.labelColor` ladder is stored white-with-alpha and flipped to
    /// black in a light window, and a system colour carries a published value
    /// per appearance. Resolution used to happen only on the way to a
    /// foreground, so `.background(.quaternary)` handed the stored value
    /// straight to the panel and painted a *white* scrim on a light window.
    /// The resolver is a lookup, so a colour the app mixed itself passes
    /// through unchanged — and it is the *background* variant of the lookup,
    /// because one rung fills differently than it writes: a light quaternary
    /// background is a bar at the window tone, not a black wash
    /// (`resolvedForBackgroundVisualEnvironment`).
    private func backgroundStyle(color: Color?, gradient: GradientType?) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            let resolved = color?.resolvedForBackgroundVisualEnvironment(
                colorScheme: context.colorScheme,
                contrast: context.colorSchemeContrast,
                backgroundProminence: context.backgroundProminence,
                systemColors: context.environmentValues.systemHighContrastColors
            )
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                return Controls.stackPanel(
                    backgroundColor: resolved,
                    backgroundGradient: gradient,
                    stackLayout: .vertical(alignment: .stretch),
                    isHitTestVisible: false,
                    children: [childNode]
                )
            }
        }
    }

    private func shapedBackgroundStyle<Clip: Shape>(
        color: Color?,
        gradient: GradientType?,
        shape: Clip,
        fillStyle: FillStyle
    ) -> some View {
        let clipStyle = (shape as? any RetainedClipShape)?.retainedClipShapeStyle ?? .rectangle
        let clipFillStyle = RetainedClipFillStyle(
            eoFill: fillStyle.isEOFilled,
            antialiased: fillStyle.isAntialiased
        )

        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            return Component { runtime in
                let baseNode = base.makeNode(runtime: runtime)
                let backgroundNode = Controls.panel(
                    backgroundColor: color,
                    backgroundGradient: gradient,
                    cornerRadius: clipStyle.staticCornerRadius,
                    clipsToBounds: true,
                    isHitTestVisible: false
                )
                backgroundNode.clipFillStyle = clipFillStyle
                let preferredSize = baseNode.intrinsicContentSize()
                let root = Controls.panel(
                    preferredSize: preferredSize,
                    layoutMode: .absolute,
                    isHitTestVisible: false,
                    children: [backgroundNode, baseNode]
                )

                root.onLayout = { bounds in
                    let frame = Rect(origin: .zero, size: bounds.size)
                    if baseNode.frame != frame {
                        baseNode.frame = frame
                    }
                    if backgroundNode.frame != frame {
                        backgroundNode.frame = frame
                    }
                    if case .capsule = clipStyle {
                        let radius = max(0, min(bounds.size.width, bounds.size.height) * 0.5)
                        if backgroundNode.cornerRadius != radius {
                            backgroundNode.cornerRadius = radius
                        }
                    }
                }

                return root
            }
        }
    }

    public func background<Background: View>(_ background: Background, alignment: Alignment = .center) -> some View {
        self.background(alignment: alignment) {
            background
        }
    }

    public func background(alignment: Alignment = .center, @ViewBuilder content backgroundContent: () -> [AnyView])
        -> some View
    {
        let backgroundViews = backgroundContent()
        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            let background = composeComponent(
                from: backgroundViews, context: context.withViewIdentityRole(.background), fallbackLayout: .absolute)

            return Component { runtime in
                let backgroundNode = background.makeNode(runtime: runtime)
                let baseNode = base.makeNode(runtime: runtime)
                let preferredSize = baseNode.intrinsicContentSize()
                let root = Controls.panel(
                    preferredSize: preferredSize,
                    layoutMode: .absolute,
                    isHitTestVisible: false,
                    children: [backgroundNode, baseNode]
                )

                if let gradient = backgroundNode.backgroundGradient {
                    let opacity = backgroundNode.opacity
                    root.backgroundGradient = opacity < 1 ? gradient.withMultipliedOpacity(opacity) : gradient
                }
                if let color = backgroundNode.backgroundColor {
                    let opacity = backgroundNode.opacity
                    root.backgroundColor = opacity < 1 ? color.retainedWithMultipliedOpacity(opacity) : color
                }

                root.onLayout = { bounds in
                    let containerSize = bounds.size
                    let baseFrame = Rect(origin: .zero, size: containerSize)
                    if baseNode.frame != baseFrame {
                        baseNode.frame = baseFrame
                    }

                    let backgroundSize = backgroundNode.intrinsicContentSize()
                    let backgroundOrigin = alignment.frameOrigin(
                        for: backgroundSize,
                        in: containerSize,
                        layoutDirection: context.layoutDirection
                    )
                    let backgroundFrame = Rect(origin: backgroundOrigin, size: backgroundSize)
                    if backgroundNode.frame != backgroundFrame {
                        backgroundNode.frame = backgroundFrame
                    }
                }

                return root
            }
        }
    }

