    public func transformPreference<Key: PreferenceKey>(
        _ key: Key.Type = Key.self,
        _ transform: @escaping (inout Key.Value) -> Void
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                var value = retainedPreferenceValue(in: childNode, key: key)
                transform(&value)
                setRetainedPreference(key, value: value, on: childNode)
                childNode.retainedPreferenceTransformBoundaries.insert(retainedPreferenceIdentifier(key))
                return childNode
            }
        }
    }

    public func anchorPreference<Key: PreferenceKey>(
        key: Key.Type = Key.self,
        value source: Anchor<Rect>.Source = .bounds,
        transform: @escaping (Anchor<Rect>) -> Key.Value
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let anchor = retainedAnchor(for: childNode, source: source, context: context)
                setRetainedPreference(key, value: transform(anchor), on: childNode)
                return childNode
            }
        }
    }

    public func transformAnchorPreference<Key: PreferenceKey>(
        key: Key.Type = Key.self,
        value source: Anchor<Rect>.Source = .bounds,
        transform: @escaping (inout Key.Value, Anchor<Rect>) -> Void
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let anchor = retainedAnchor(for: childNode, source: source, context: context)
                var value = retainedPreferenceValue(in: childNode, key: key)
                transform(&value, anchor)
                setRetainedPreference(key, value: value, on: childNode)
                childNode.retainedPreferenceTransformBoundaries.insert(retainedPreferenceIdentifier(key))
                return childNode
            }
        }
    }

    public func onPreferenceChange<Key: PreferenceKey>(
        _ key: Key.Type = Key.self,
        perform action: @escaping (Key.Value) -> Void,
        fileID: String = #fileID,
        line: Int = #line,
        column: Int = #column
    ) -> some View where Key.Value: Equatable {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            if let attribution = context.viewIdentity.lazyList {
                return lazyListSyntheticComponent(
                    in: child, context: context, attribution: attribution, kind: .preferenceObservation,
                    stage: { nodes, _, group in
                        stageLazyPreferenceChangeObservation(
                            in: nodes, key: key, action: action, context: context,
                            attribution: attribution, group: group)
                    })
            }
            if let attribution = context.viewIdentity.descriptorComponent {
                return descriptorSyntheticComponent(
                    in: child.asSingleNode(), context: context, attribution: attribution, kind: .preferenceObservation,
                    stage: { nodes, _, group in
                        stageDescriptorPreferenceChangeObservation(
                            in: nodes, key: key, action: action, context: context,
                            attribution: attribution, group: group)
                    })
            }
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                stagePreferenceChangeObservation(in: childNode, key: key, action: action, context: context)
                return childNode
            }
        }
    }

