    public func onDeleteCommand(perform action: (() -> Void)?) -> some View {
        keyCommandModifier { event in
            switch event.key {
            case .backspace, .deleteForward:
                action?()
                return true

            default:
                return false
            }
        }
    }

    public func onMoveCommand(perform action: ((MoveCommandDirection) -> Void)?) -> some View {
        keyCommandModifier { event in
            let direction: MoveCommandDirection
            switch event.key {
            case .upArrow:
                direction = .up
            case .downArrow:
                direction = .down
            case .leftArrow:
                direction = .left
            case .rightArrow:
                direction = .right
            default:
                return false
            }

            action?(direction)
            return true
        }
    }

