    public func mask(alignment: Alignment = .center, @ViewBuilder _ mask: () -> [AnyView]) -> some View {
        self.mask(alignment: alignment, inverse: false, mask)
    }

    public func mask<Mask: View>(_ mask: Mask, inverse: Bool) -> some View {
        self.mask(alignment: .center, inverse: inverse) {
            mask
        }
    }

    public func inverseMask<Mask: View>(_ mask: Mask) -> some View {
        self.mask(mask, inverse: true)
    }

    public func mask(
        alignment: Alignment = .center,
        inverse: Bool,
        @ViewBuilder _ mask: () -> [AnyView]
    ) -> some View {
        let maskViews = mask()
        return ModifiedView(content: self) { content, context in
            let base = content.makeComponent(context: context)
            let maskSource = composeComponent(
                from: maskViews, context: context.withViewIdentityRole(.mask), fallbackLayout: .absolute)
            var retainedMask = alignment.retainedViewMask
            retainedMask.isInverse = inverse

            return Component { runtime in
                let baseNode = base.makeNode(runtime: runtime)
                let maskNode = maskSource.makeNode(runtime: runtime)
                maskNode.isHidden = true
                let preferredSize = baseNode.intrinsicContentSize()
                let root = Controls.panel(
                    preferredSize: preferredSize,
                    layoutMode: .absolute,
                    isHitTestVisible: false,
                    children: [baseNode, maskNode]
                )
                root.viewMask = retainedMask

                root.onLayout = { bounds in
                    let containerSize = bounds.size
                    let baseFrame = Rect(origin: .zero, size: containerSize)
                    if baseNode.frame != baseFrame {
                        baseNode.frame = baseFrame
                    }

                    let maskSize = maskNode.intrinsicContentSize()
                    let maskOrigin = alignment.frameOrigin(
                        for: maskSize,
                        in: containerSize,
                        layoutDirection: context.layoutDirection
                    )
                    let maskFrame = Rect(origin: maskOrigin, size: maskSize)
                    if maskNode.frame != maskFrame {
                        maskNode.frame = maskFrame
                    }
                }

                return root
            }
        }
    }

