    fileprivate func onLongPressGestureModifier(
        minimumDuration: Double,
        maximumDistance: CGFloat,
        action: @escaping () -> Void,
        pressingChanged: ((Bool) -> Void)?,
        begin: (@MainActor (RetainedLongPressGesture.IsActive) -> RetainedLongPressGesture.Cleanup?)? = nil
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                childNode.isHitTestVisible = true
                childNode.longPressGesture = RetainedLongPressGesture(
                    minimumDuration: minimumDuration,
                    maximumDistance: Double(maximumDistance),
                    isEnabled: context.isEnabled,
                    onBegin: begin,
                    onPressingChanged: { isPressing in pressingChanged?(isPressing) },
                    onRecognized: { action() }
                )

                return childNode
            }
        }
    }

    public func onKeyPress(
        keys: Set<KeyEquivalent>,
        phases: KeyPress.Phases = .all,
        action: @escaping (KeyPress) -> KeyPress.Result
    ) -> some View {
        ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let childNode = child.makeNode(runtime: runtime)
                let existingOnKeyDown = childNode.onKeyDown
                childNode.onKeyDown = { event in
                    guard let scalar = UnicodeScalar(event.keyCode) else {
                        existingOnKeyDown?(event)
                        return
                    }
                    let key = KeyEquivalent(unicodeScalarLiteral: scalar)
                    guard keys.contains(key) else {
                        existingOnKeyDown?(event)
                        return
                    }
                    var phase: KeyPress.Phases = .down
                    if event.isRepeat {
                        phase = .repeat
                    }
                    guard phases.contains(phase) else {
                        existingOnKeyDown?(event)
                        return
                    }
                    let press = KeyPress(key: key, characters: "", phases: phase)
                    let result = action(press)
                    if result == .ignored {
                        existingOnKeyDown?(event)
                    }
                }
                return childNode
            }
        }
    }

