    /// Assign a stable identity to this view so the diffing algorithm can
    /// match it across rebuilds by identity rather than position.
    public func id(_ identifier: String) -> some View {
        var modified = ModifiedView(content: self) { content, context in
            content.makeComponent(context: context)
        }
        modified.id = identifier
        modified.explicitViewIdentity = RetainedViewIdentity.Key(identifier)
        modified.scrollTargetIdentity = RetainedScrollTargetIdentity(identifier: identifier, isImplicitForEach: false)
        return modified
    }

    public func id<ID: Hashable>(_ identifier: ID) -> some View {
        var modified = ModifiedView(content: self) { content, context in
            content.makeComponent(context: context)
        }
        modified.id = String(describing: identifier)
        modified.explicitViewIdentity = RetainedViewIdentity.Key(identifier)
        modified.scrollTargetIdentity = RetainedScrollTargetIdentity(identifier: identifier, isImplicitForEach: false)
        return modified
    }

    func implicitForEachScrollTarget<ID: Hashable>(_ identifier: ID, index: Int) -> some View {
        var modified = ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let node = child.makeNode(runtime: runtime)
                let key = retainedContainerValuesIdentifier()
                var values = node.retainedContainerValues[key] as? ContainerValues ?? ContainerValues()
                values.setImplicitSymbolTag(identifier)
                node.retainedContainerValues[key] = values
                return node
            }
        }
        modified.id = "\(identifier)#\(index)"
        modified.setImplicitForEachIdentity(identifier)
        return modified
    }

    public func tag<Tag: Hashable>(_ tag: Tag) -> some View {
        var modified = ModifiedView(content: self) { content, context in
            let child = content.makeComponent(context: context)
            return Component { runtime in
                let node = child.makeNode(runtime: runtime)
                let identifier = retainedContainerValuesIdentifier()
                var values = node.retainedContainerValues[identifier] as? ContainerValues ?? ContainerValues()
                values.setTag(tag)
                node.retainedContainerValues[identifier] = values
                return node
            }
        }
        modified.selectionTag = AnyHashable(tag)
        return modified
    }

