@MainActor
private func attachSubmitHandler(
    to node: ViewNode,
    triggers: SubmitTriggers,
    action: @escaping () -> Void,
    invalidate: @escaping () -> Void,
    isRoot: Bool = true
) {
    if !isRoot && node.isSubmitScopeBoundary {
        if let raw = node.submitScopeTriggersRawValue {
            let blockedTriggers = SubmitTriggers(rawValue: raw)
            if !blockedTriggers.intersection(triggers).isEmpty {
                return
            }
        } else {
            return
        }
    }

    if node.onKeyDown != nil {
        let existingOnKeyDown = node.onKeyDown
        node.onKeyDown = { event in
            guard event.key == .enter, triggers.submitsTextInput else {
                existingOnKeyDown?(event)
                return
            }

            action()
            invalidate()
        }
    }

    for child in node.children {
        attachSubmitHandler(
            to: child,
            triggers: triggers,
            action: action,
            invalidate: invalidate,
            isRoot: false
        )
    }
}
